import React, { useEffect, useMemo, useState } from 'react';
import {
  Activity, AlertTriangle, BarChart3, CheckCircle2, Database, FileText, Flag, Globe,
  History, Lock, MessageSquare, RefreshCw, Save, Search, Server, Settings2, Shield,
  Trash2, UserCog, Users, Wrench, XCircle, UserCheck, UserX, EyeOff, RotateCcw,
  Copy, Pin, Archive, Unlock, Ban, KeyRound, Radio, UploadCloud, Brain, CircleDollarSign
} from 'lucide-react';
import { auth, checkIsAdmin } from '../lib/firebase';
import { getAllCommunityUsers, adminChangeUserHandle } from '../lib/community';
import {
  getSiteConfig, saveSiteConfig, createSiteConfigBackup, getSiteConfigBackups, restoreSiteConfigBackup,
  DEFAULT_TOP_NAVIGATION, DEFAULT_MENU_NAVIGATION, fetchAllArticlesForAdmin, saveArticle, deleteArticle,
  setArticleFeaturedStatus, getArticleRevisions, restoreArticleRevision,
  duplicateArticleFromRevision, ArticleRevision, promoteCommunityBlogToMain, unpublishMainArticle, approvePublicBlogEdit
} from '../lib/cms';
import { CommunityUser, SiteConfig, Article } from '../types';
import {
  getAdminRootAndCommunityPosts, getCommunities, getReports, getPlatformModerators, deleteCommunity, adminSetCommunitySettings,
  adminUpdateUser, adminDeleteUserProfile, adminDeleteRootPost, adminDeleteCommunityPost,
  adminSetRootPostFeatured, adminSetRootPostModeration, adminSetCommunityPostFeatured, SocialAdminPost, SocialCommunity, SocialReport,
  adminSetCommunityPostModeration, adminUpdateRootPost, adminUpdateCommunityPost, getQuestions, updateQuestion, deleteQuestion, moderateQuestion, mergeQuestions,
  getTopics, updateTopic, deleteTopic, getAdminMessages, adminUpdateMessage, adminDeleteMessage, updateCommunity, addPlatformModerator,
  removePlatformModerator
} from '../lib/social';
import { getSeriesList, updateSeries, deleteSeries } from '../lib/series';
import { runClientHealthChecks, HealthCheckResult, buildHealthSummary } from '../lib/health';
import {
  DEFAULT_EMERGENCY_CONTROLS, EmergencyControls, resolveMasterAccess,
  subscribeEmergencyControls, updateEmergencyControls, listMasterAdmins,
  grantMasterAdminByEmail, grantMasterAdminByUid, revokeMasterAdmin,
  promoteModeratorByUid, revokeModeratorByUid, updateUserControls, forceProfileCleanup,
  resetUserPreferences, getPlatformAnalytics, getRecommendationHealth, PlatformAnalytics,
  hideOrRestoreArticleComment, deleteArticleCommentAsMaster, hideOrRestorePostComment, hideOrRestoreCommunityPostComment,
  deletePostCommentAsMaster, deleteCommunityPostCommentAsMaster, setArticleCommentsLocked, setPostCommentsLocked,
  getPlatformAnalytics as getCloudAnalytics, getModeratorPermissionSet, setModeratorPermissionSet, getIntelligenceActivityHealth, IntelligenceActivityHealth,
  getRecentCommentsForMaster, removeArticleCommentReplies, MasterAdminEntry, MasterCommentRecord, RecommendationHealth,
  setReportStatus, getActivePresenceCount, getReportsForMaster
} from '../lib/masterControl';
import { notifyToast } from '../lib/toast';
import { MediaUploadButton } from './MediaUploadButton';
import { ProblemReport, ChangelogEntry, getProblemReportsForAdmin, updateProblemReport, ProblemStatus, getChangelogEntriesForAdmin, createChangelogEntry, updateChangelogEntry, deleteChangelogEntry } from '../lib/siteFeatures';
import { DEFAULT_INTELLIGENCE_FLAGS, IntelligenceFeatureFlags, subscribeIntelligenceFlags, setIntelligenceFlags } from '../lib/featureFlags';
import { AI_THEME_KEYS, DEFAULT_AI_THEME, validateAITheme, saveAITheme } from '../lib/aiTheme';
import { CommerceAdminPanel } from './CommerceAdminPanel';
import type { AIThemeConfig } from '../types';

interface Props { onSiteConfigRestored?: () => Promise<void> | void; isModerator?: boolean; }
type Section = 'dashboard'|'access'|'users'|'posts'|'communities'|'questions'|'topics'|'messages'|'moderators'|'reports'|'comments'|'content'|'site'|'navigation'|'backups'|'moderation'|'config'|'analytics'|'recommendations'|'intelligence'|'commerce'|'system'|'audit'|'changelog';
const pill = (active = false) => `border-2 border-black px-3 py-2 font-mono text-[10px] font-black ${active ? 'bg-[var(--color-primary)]' : 'bg-white hover:bg-neutral-100'}`;
const danger = `border-2 border-black bg-red-100 px-3 py-2 font-mono text-[10px] font-black hover:bg-red-200`;

export const AdminControlPanel: React.FC<Props> = ({ onSiteConfigRestored, isModerator = false }) => {
  const [master, setMaster] = useState(checkIsAdmin(auth.currentUser?.email));
  const [section, setSection] = useState<Section>('dashboard');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState('');
  const [notice, setNotice] = useState('');
  const [cloudErrors, setCloudErrors] = useState<string[]>([]);
  const [reportResponse, setReportResponse] = useState('');
  const [site, setSite] = useState<SiteConfig | null>(null);
  const [controls, setControls] = useState<EmergencyControls>(DEFAULT_EMERGENCY_CONTROLS);
  const [users, setUsers] = useState<CommunityUser[]>([]);
  const [posts, setPosts] = useState<SocialAdminPost[]>([]);
  const [communities, setCommunities] = useState<SocialCommunity[]>([]);
  const [questions, setQuestions] = useState<any[]>([]);
  const [topics, setTopics] = useState<any[]>([]);
  const [messages, setMessages] = useState<any[]>([]);
  const [reports, setReports] = useState<SocialReport[]>([]);
  const [backups, setBackups] = useState<any[]>([]);
  const [navTop, setNavTop] = useState<any[]>(DEFAULT_TOP_NAVIGATION);
  const [navMenu, setNavMenu] = useState<any[]>(DEFAULT_MENU_NAVIGATION);
  const [backupLabel, setBackupLabel] = useState('');
  const [editingCommunity, setEditingCommunity] = useState<SocialCommunity | null>(null);
  const [editingMessage, setEditingMessage] = useState<any | null>(null);
  const [messageDraft, setMessageDraft] = useState('');
  const [moderators, setModerators] = useState<any[]>([]);
  const [articles, setArticles] = useState<Article[]>([]);
  const [series, setSeries] = useState<any[]>([]);
  const [admins, setAdmins] = useState<MasterAdminEntry[]>([]);
  const [analytics, setAnalytics] = useState<PlatformAnalytics | null>(null);
  const [health, setHealth] = useState<HealthCheckResult[]>([]);
  const [recommendationHealth, setRecommendationHealth] = useState<RecommendationHealth | null>(null);
  const [activityHealth, setActivityHealth] = useState<IntelligenceActivityHealth | null>(null);
  const [intelligenceFlags, setIntelligenceFlagsState] = useState<IntelligenceFeatureFlags>(DEFAULT_INTELLIGENCE_FLAGS);
  const [audit, setAudit] = useState<any[]>([]);
  const [comments, setComments] = useState<MasterCommentRecord[]>([]);
  const [presence, setPresence] = useState<{activeUsers:number;measuredAt:number} | null>(null);
  const [emailGrant, setEmailGrant] = useState('');
  const [uidGrant, setUidGrant] = useState('');
  const [editingUser, setEditingUser] = useState<CommunityUser | null>(null);
  const [userPatch, setUserPatch] = useState<any>({});
  const [editingArticle, setEditingArticle] = useState<Article | null>(null);
  const [articleJson, setArticleJson] = useState('');
  const [revisionArticle, setRevisionArticle] = useState<Article | null>(null);
  const [revisions, setRevisions] = useState<ArticleRevision[]>([]);
  const [commentTarget, setCommentTarget] = useState<MasterCommentRecord | null>(null);
  const [moderatorPermissions, setModeratorPermissions] = useState<Record<string, boolean>>({});
  const [permissionTarget, setPermissionTarget] = useState<any | null>(null);
  const [problemReports, setProblemReports] = useState<ProblemReport[]>([]);
  const [problemCommentDrafts, setProblemCommentDrafts] = useState<Record<string,string>>({});
  const [changelogEntries, setChangelogEntries] = useState<Array<ChangelogEntry & {id:string}>>([]);
  const [changelogDraft, setChangelogDraft] = useState({id:'',version:'',date:'',title:'',changes:'',kind:'feature' as any});
  const [aiThemeDraft, setAiThemeDraft] = useState<AIThemeConfig>(DEFAULT_AI_THEME);
  const [savedAiTheme, setSavedAiTheme] = useState<AIThemeConfig>(DEFAULT_AI_THEME);

  const msg = (text: string, type: 'success'|'error' = 'success') => { setNotice(text); notifyToast(text, type); };

  const loadCore = async () => {
    setLoading(true);
    setCloudErrors([]);
    const errors: string[] = [];
    try {
      const results = await Promise.allSettled([
        getSiteConfig(),
        getAllCommunityUsers(),
        getAdminRootAndCommunityPosts(),
        getCommunities(),
        master ? getReportsForMaster() : getReports(),
        fetchAllArticlesForAdmin(),
        getSeriesList(200),
      ]);
      const [siteResult,userResult,postResult,communityResult,reportResult,articleResult,seriesResult] = results;
      if (siteResult.status==='fulfilled') {
        const siteData=siteResult.value;
        const loadedAITheme = siteData.aiTheme ? { ...DEFAULT_AI_THEME, ...siteData.aiTheme } as AIThemeConfig : DEFAULT_AI_THEME;
        setAiThemeDraft(loadedAITheme);
        setSavedAiTheme(loadedAITheme);
        setSite(siteData);
        setControls({ ...DEFAULT_EMERGENCY_CONTROLS, ...siteData } as EmergencyControls);
        setNavTop(siteData.topNavigation?.length ? siteData.topNavigation : DEFAULT_TOP_NAVIGATION);
        setNavMenu(siteData.menuNavigation?.length ? siteData.menuNavigation : DEFAULT_MENU_NAVIGATION);
      } else errors.push(`Site config: ${siteResult.reason?.message||String(siteResult.reason)}`);
      if (userResult.status==='fulfilled') setUsers(userResult.value); else errors.push(`Users: ${userResult.reason?.message||String(userResult.reason)}`);
      if (postResult.status==='fulfilled') setPosts(postResult.value); else errors.push(`Posts: ${postResult.reason?.message||String(postResult.reason)}`);
      if (communityResult.status==='fulfilled') setCommunities(communityResult.value); else errors.push(`Communities: ${communityResult.reason?.message||String(communityResult.reason)}`);
      if (reportResult.status==='fulfilled') setReports(reportResult.value as any); else errors.push(`Reports: ${reportResult.reason?.message||String(reportResult.reason)}`);
      if (articleResult.status==='fulfilled') setArticles(articleResult.value); else errors.push(`Articles: ${articleResult.reason?.message||String(articleResult.reason)}`);
      if (seriesResult.status==='fulfilled') setSeries(seriesResult.value); else errors.push(`Series: ${seriesResult.reason?.message||String(seriesResult.reason)}`);

      if (master) {
        const masterResults = await Promise.allSettled([
          getQuestions(), getTopics(), getAdminMessages(), getSiteConfigBackups(), getPlatformModerators(), listMasterAdmins(), getRecentCommentsForMaster(), getActivePresenceCount(), getProblemReportsForAdmin(), getChangelogEntriesForAdmin()
        ]);
        const [q,t,m,b,mods,access,recentComments,h,problems,changelog] = masterResults;
        const labels=['Questions','Topics','Messages','Backups','Moderators','Master admins','Comments','Presence','Problem reports','Changelog'];
        [q,t,m,b,mods,access,recentComments,h,problems].forEach((r,i)=>{ if(r.status==='rejected') errors.push(`${labels[i]}: ${r.reason?.message||String(r.reason)}`); });
        if(q.status==='fulfilled') setQuestions(q.value);
        if(t.status==='fulfilled') setTopics(t.value);
        if(changelog.status==='fulfilled') setChangelogEntries(changelog.value as any);
        if(m.status==='fulfilled') setMessages(m.value);
        if(b.status==='fulfilled') setBackups(b.value);
        if(mods.status==='fulfilled') setModerators(mods.value);
        if(access.status==='fulfilled') setAdmins(access.value);
        if(recentComments.status==='fulfilled') setComments(recentComments.value);
        if(h.status==='fulfilled') setPresence(h.value);
        if(problems.status==='fulfilled') setProblemReports(problems.value);
      }
    } finally {
      setCloudErrors(errors);
      setLoading(false);
      if(errors.length) msg(`Cloud data loaded with ${errors.length} failed check(s). See diagnostics below.`, 'error');
    }
  };

  useEffect(() => {
    let stopped = false;
    const unsub = auth.onAuthStateChanged(async user => {
      if (!user) { if (!stopped) setMaster(false); return; }
      const resolved = await resolveMasterAccess(user);
      if (!stopped) setMaster(resolved);
    });
    return () => { stopped = true; unsub(); };
  }, []);
  useEffect(() => { if (master || isModerator) void loadCore(); }, [master, isModerator]);
  useEffect(() => { if (!master) return; const unsub = subscribeEmergencyControls(setControls); return () => unsub(); }, [master]);
  useEffect(() => { if (!master || section !== 'analytics') return; void runAnalytics(); const id=window.setInterval(()=>void runAnalytics(),30000); return ()=>window.clearInterval(id); }, [master, section]);
  useEffect(() => { if (!master) return; return subscribeIntelligenceFlags(setIntelligenceFlagsState); }, [master]);

  const filteredUsers = useMemo(() => { const q = search.toLowerCase().trim(); return !q ? users : users.filter(u => `${u.username} ${u.displayName} ${u.email || ''}`.toLowerCase().includes(q)); }, [users, search]);
  const filteredPosts = useMemo(() => { const q = search.toLowerCase().trim(); return !q ? posts : posts.filter(p => `${p.title} ${p.content} ${p.authorUsername} ${p.communitySlug || ''}`.toLowerCase().includes(q)); }, [posts, search]);
  const filteredComments = useMemo(() => { const q = search.toLowerCase().trim(); return !q ? comments : comments.filter(c => `${c.authorUsername} ${c.authorName} ${c.content} ${c.path}`.toLowerCase().includes(q)); }, [comments, search]);
  const openReports = useMemo(() => reports.filter(r => ['open','under_review','action_taken'].includes(r.status)), [reports]);

  const saveEmergency = async (patch: Partial<EmergencyControls>) => {
    if (!master) return; setSaving(true);
    try { await updateEmergencyControls(patch); setSite(s=>s?{...s,...patch}:s); msg('Cloud emergency control updated. All clients receive the change through the live site-config listener.'); }
    catch(e:any){ msg(e?.message||'Emergency control save failed.','error'); }
    finally{ setSaving(false); }
  };

  const saveUserControls = async () => {
    if (!editingUser) return;
    try {
      const nextHandle=String(userPatch.username||'').toLowerCase().trim().replace(/[^a-z0-9_]/g,'').slice(0,30);
      const profile:any={displayName:userPatch.displayName,bio:userPatch.bio,photoURL:userPatch.photoURL,coverImageUrl:userPatch.coverImageUrl,websiteUrl:userPatch.websiteUrl,location:userPatch.location,socialX:userPatch.socialX,socialGithub:userPatch.socialGithub,socialTelegram:userPatch.socialTelegram,socialInstagram:userPatch.socialInstagram,isVerified:userPatch.isVerified};
      const moderation:any={isBlocked:userPatch.isBlocked,isSuspended:userPatch.isSuspended,suspensionUntil:userPatch.suspensionUntil,restrictCommenting:userPatch.restrictCommenting,restrictPosting:userPatch.restrictPosting,restrictCommunities:userPatch.restrictCommunities,restrictReactions:userPatch.restrictReactions,restrictFollowing:userPatch.restrictFollowing,moderatorNote:userPatch.moderatorNote,warningCount:userPatch.warningCount};
      await adminUpdateUser(editingUser.uid,profile);
      await updateUserControls(editingUser.uid,moderation);
      if(nextHandle!==String(editingUser.username||'').toLowerCase()) await adminChangeUserHandle(editingUser.uid,nextHandle);
      setEditingUser(null); await loadCore(); msg(`@${editingUser.username||'user'} profile, handle, and moderation state saved to Firestore.`);
    } catch(e:any){ msg(e?.message||'User control update failed.','error'); }
  };

  const toggleVerification = async (u: CommunityUser) => {
    try { await adminUpdateUser(u.uid,{isVerified:!u.isVerified}); await loadCore(); msg(`@${u.username} verification state updated in cloud.`); }
    catch(e:any){ msg(e?.message||'Verification update failed.','error'); }
  };

  const removeUser = async (u: CommunityUser) => {
    if (!confirm(`Delete the Firestore profile for @${u.username}? Firebase Authentication is a separate account and is not silently claimed as deleted.`)) return;
    try { await adminDeleteUserProfile(u.uid); await loadCore(); msg(`@${u.username} profile document deleted.`); }
    catch(e:any){ msg(e?.message||'Profile deletion failed.','error'); }
  };

  const editArticle = (a: Article) => { setEditingArticle(a); setArticleJson(JSON.stringify(a,null,2)); };
  const saveEditedArticle = async () => {
    if (!editingArticle) return;
    try { const parsed = JSON.parse(articleJson); await saveArticle(parsed); setEditingArticle(null); await loadCore(); msg(`Article ${parsed.slug} saved to Firestore.`); }
    catch(e:any){ msg(e?.message||'Article JSON/save failed.','error'); }
  };
  const togglePublished = async (a: Article) => {
    try { await saveArticle({...a,isPublished:!a.isPublished,mainPublicationStatus:!a.isPublished?'published':'unpublished'} as Article,{createRevision:true,revisionAction:'manual'}); await loadCore(); msg(`${a.slug} publication state updated.`); }
    catch(e:any){ msg(e?.message||'Publish state update failed.','error'); }
  };
  const toggleFeature = async (a: Article) => {
    try { await setArticleFeaturedStatus(a,!a.featured,!a.featured); await loadCore(); msg(`${a.slug} feature/pin state updated.`); }
    catch(e:any){ msg(e?.message||'Feature update failed.','error'); }
  };
  const archiveArticle = async (a: Article) => {
    try { await saveArticle({...a,isArchived:true,isPublished:false,mainPublicationStatus:'unpublished'} as any,{createRevision:true,revisionAction:'manual'}); await loadCore(); msg(`${a.slug} archived.`); }
    catch(e:any){ msg(e?.message||'Archive failed.','error'); }
  };
  const removeArticle = async (a: Article) => {
    if(!confirm(`Delete article ${a.slug}?`)) return;
    try { await deleteArticle(a.slug); await loadCore(); msg(`${a.slug} deleted from Firestore.`); }
    catch(e:any){ msg(e?.message||'Article delete failed.','error'); }
  };
  const loadRevisions = async (a: Article) => {
    try { setRevisionArticle(a); setRevisions(await getArticleRevisions(a.slug)); }
    catch(e:any){ msg(e?.message||'Revision history load failed.','error'); }
  };
  const restoreRevision = async (r: ArticleRevision) => {
    if(!confirm(`Restore revision for ${r.slug}? A before-restore snapshot is created first.`)) return;
    try { await restoreArticleRevision(r.id); setRevisionArticle(null); await loadCore(); msg(`Revision restored for ${r.slug}.`); }
    catch(e:any){ msg(e?.message||'Revision restore failed.','error'); }
  };
  const duplicateRevision = async (r: ArticleRevision) => {
    try { await duplicateArticleFromRevision(r.id); await loadCore(); msg(`Revision duplicated as a new unpublished article.`); }
    catch(e:any){ msg(e?.message||'Revision duplicate failed.','error'); }
  };

  const runAnalytics = async () => { try { setAnalytics(await getCloudAnalytics()); msg('Platform analytics loaded from Firestore aggregate counts.'); } catch(e:any){ msg(e?.message||'Analytics query failed.','error'); } };
  const runRecommendations = async () => { try { setRecommendationHealth(await getRecommendationHealth()); msg('Recommendation source health checked against Firestore.'); } catch(e:any){ msg(e?.message||'Recommendation health failed.','error'); } };
  const runActivityHealth = async () => { try { setActivityHealth(await getIntelligenceActivityHealth()); msg('V80 activity-event health loaded from Firestore.'); } catch(e:any){ msg(e?.message||'Activity health failed.','error'); } };
  const saveIntelligenceFlag = async (key: keyof IntelligenceFeatureFlags, value: boolean) => { try { await setIntelligenceFlags({[key]: value}); msg(`${String(key)} intelligence flag saved server-side.`); } catch(e:any){ msg(e?.message||'Intelligence flag save failed.','error'); } };
  const updateAIThemeDraft = (key: keyof AIThemeConfig, value: string) => { setAiThemeDraft(prev => ({ ...prev, [key]: value })); };
  const saveAIThemeSettings = async () => {
    if (!site) return;
    const checked = validateAITheme(aiThemeDraft);
    if (!checked.valid) { msg(checked.errors.join(' '), 'error'); return; }
    setSaving(true);
    try {
      await saveAITheme(checked.theme);
      const next = { ...site, aiTheme: checked.theme };
      setSite(next);
      setAiThemeDraft(checked.theme);
      setSavedAiTheme(checked.theme);
      msg('AI appearance saved to Firestore and synchronized site-wide.');
    } catch (e:any) { msg(e?.message || 'AI appearance save failed.', 'error'); }
    finally { setSaving(false); }
  };
  const resetAIThemeSettings = () => setAiThemeDraft(DEFAULT_AI_THEME);
  const cancelAIThemeChanges = () => setAiThemeDraft(savedAiTheme);
  const applyAIPreset = (name: string) => {
    const presets: Record<string, AIThemeConfig> = {
      DEFAULT: DEFAULT_AI_THEME,
      NEON: { ...DEFAULT_AI_THEME, primary:'#FF00E5', assistantMessage:'#FF00E5', header:'#FF00E5', active:'#00E0FF', hover:'#FFD600' },
      MONOCHROME: { ...DEFAULT_AI_THEME, primary:'#111111', secondary:'#555555', accent:'#999999', background:'#FFFFFF', surface:'#F3F3F3', border:'#000000', text:'#000000', mutedText:'#555555', buttonText:'#FFFFFF', hover:'#DDDDDD', active:'#333333', inputBackground:'#FFFFFF', inputBorder:'#000000', userMessage:'#FFFFFF', assistantMessage:'#E8E8E8', source:'#D6D6D6', link:'#111111', icon:'#000000', header:'#111111' },
      BLUE: { ...DEFAULT_AI_THEME, primary:'#2563EB', secondary:'#0EA5E9', accent:'#38BDF8', assistantMessage:'#DBEAFE', header:'#2563EB', active:'#1D4ED8', hover:'#BAE6FD', link:'#1D4ED8' },
      PURPLE: { ...DEFAULT_AI_THEME, primary:'#7C3AED', secondary:'#A855F7', accent:'#D946EF', assistantMessage:'#F3E8FF', header:'#7C3AED', active:'#6D28D9', hover:'#E9D5FF', link:'#6D28D9' },
      GREEN: { ...DEFAULT_AI_THEME, primary:'#16A34A', secondary:'#22C55E', accent:'#84CC16', assistantMessage:'#DCFCE7', header:'#16A34A', active:'#15803D', hover:'#D9F99D', link:'#166534' },
      RED: { ...DEFAULT_AI_THEME, primary:'#DC2626', secondary:'#F97316', accent:'#FB7185', assistantMessage:'#FEE2E2', header:'#DC2626', active:'#B91C1C', hover:'#FED7AA', link:'#B91C1C' },
      AMBER: { ...DEFAULT_AI_THEME, primary:'#F59E0B', secondary:'#FBBF24', accent:'#FDE047', assistantMessage:'#FEF3C7', header:'#F59E0B', active:'#D97706', hover:'#FEF08A', link:'#B45309' },
    };
    if (presets[name]) setAiThemeDraft(presets[name]);
  };
  const luminance = (hex:string) => { const rgb=hex.replace('#','').match(/.{2}/g)?.map(v=>parseInt(v,16)/255) || [0,0,0]; const mapped=rgb.map(v=>v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)); return 0.2126*mapped[0]+0.7152*mapped[1]+0.0722*mapped[2]; };
  const contrastRatio = (a:string,b:string) => { const l1=luminance(a), l2=luminance(b); return (Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05); };

  const runHealth = async () => { try { setHealth(await runClientHealthChecks()); setPresence(await getActivePresenceCount()); } catch(e:any){ msg(e?.message||'Health check failed.','error'); } };
  const loadAudit = async () => { try { const {getAuditLog}=await import('../lib/masterControl'); setAudit(await getAuditLog()); } catch(e:any){ msg(e?.message||'Audit log failed.','error'); } };
  const loadComments = async () => { try { setComments(await getRecentCommentsForMaster()); } catch(e:any){ msg(e?.message||'Comment load failed.','error'); } };
  const openPermissions = async (m:any) => { try { setPermissionTarget(m); setModeratorPermissions(await getModeratorPermissionSet(m.uid)); } catch(e:any){ msg(e?.message||'Permission load failed.','error'); } };
  const savePermissions = async () => { if(!permissionTarget) return; try { await setModeratorPermissionSet(permissionTarget.uid,moderatorPermissions); setPermissionTarget(null); await loadCore(); msg(`Permissions for @${permissionTarget.username} saved to Firestore.`); } catch(e:any){ msg(e?.message||'Permission update failed.','error'); } };
  const runReportStatus = async (r: SocialReport, status: 'under_review'|'action_taken'|'dismissed'|'resolved') => { try { await setReportStatus(r.id,status,reportResponse); setReportResponse(''); await loadCore(); msg(`Report ${r.id} moved to ${status}.`); } catch(e:any){ msg(e?.message||'Report status update failed.','error'); } };
  const moveNav = (which:'top'|'menu', index:number, delta:number) => { const source=which==='top'?navTop:navMenu; const j=index+delta; if(j<0||j>=source.length)return; const next=[...source]; [next[index],next[j]]=[next[j],next[index]]; which==='top'?setNavTop(next):setNavMenu(next); };
  const saveNavigation = async () => { if(!site) return; try { const next={...site,topNavigation:navTop,menuNavigation:navMenu}; await saveSiteConfig(next); setSite(next); msg('Navigation saved to Firestore and will propagate through site-config listeners.'); } catch(e:any){ msg(e?.message||'Navigation save failed.','error'); } };
  const createBackup = async () => { try { if(!site) throw new Error('Site configuration has not loaded.'); await createSiteConfigBackup(site, backupLabel || 'Manual backup'); setBackupLabel(''); await loadCore(); msg('Global settings backup created in Firestore.'); } catch(e:any){ msg(e?.message||'Backup creation failed.','error'); } };
  const saveCommunity = async () => { if(!editingCommunity) return; try { await updateCommunity(editingCommunity.id, auth.currentUser?.uid || '', {name:editingCommunity.name,description:editingCommunity.description,iconUrl:editingCommunity.iconUrl||'',bannerUrl:editingCommunity.bannerUrl||'',rules:editingCommunity.rules||[],isPrivate:!!editingCommunity.isPrivate,isArchived:!!editingCommunity.isArchived,isLocked:!!editingCommunity.isLocked,allowLinks:editingCommunity.allowLinks!==false,allowMedia:editingCommunity.allowMedia!==false,defaultPostType:editingCommunity.defaultPostType||'discussion'}); setEditingCommunity(null); await loadCore(); msg('Community configuration saved to Firestore.'); } catch(e:any){ msg(e?.message||'Community update failed.','error'); } };

  const saveNewChangelog = async () => {
    try {
      const changes = changelogDraft.changes.split('\n').map(x=>x.trim()).filter(Boolean);
      if (!changelogDraft.version.trim() || !changelogDraft.date.trim() || !changelogDraft.title.trim() || !changes.length) throw new Error('Version, date, title and at least one change are required.');
      const payload = { version: changelogDraft.version.trim(), date: changelogDraft.date.trim(), title: changelogDraft.title.trim(), changes, kind: changelogDraft.kind };
      if (changelogDraft.id) await updateChangelogEntry(changelogDraft.id, payload); else await createChangelogEntry(payload);
      setChangelogDraft({id:'',version:'',date:'',title:'',changes:'',kind:'feature'});
      setChangelogEntries(await getChangelogEntriesForAdmin());
      msg(changelogDraft.id ? 'Changelog entry updated in Firestore.' : 'Changelog entry published to Firestore.');
    } catch(e:any){ msg(e?.message||'Changelog save failed.','error'); }
  };
  const removeChangelog = async (id:string) => { try { await deleteChangelogEntry(id); setChangelogEntries(await getChangelogEntriesForAdmin()); msg('Changelog entry deleted from Firestore.'); } catch(e:any){ msg(e?.message||'Changelog delete failed.','error'); } };

  if (!master && !isModerator) return <div className="p-8 border-4 border-red-600 bg-red-50 font-mono text-xs font-black">ACCESS DENIED — MASTER/STAFF ACCOUNT REQUIRED.</div>;

  const tabs: Array<[Section,string,any,boolean]> = [
    ['dashboard','DASHBOARD',Database,true],['commerce','COMMERCE',CircleDollarSign,master],['access','ACCESS',Shield,master],['users','USERS',Users,master],['posts','POSTS',FileText,master],['communities','COMMUNITIES',Globe,master],['questions','QUESTIONS',FileText,master],['topics','TOPICS',Search,master],['reports','REPORTS',Flag,master],['messages','MESSAGES',MessageSquare,master],['moderators','MODERATORS',UserCog,master],['comments','COMMENTS',MessageSquare,master],['content','CONTENT',FileText,master],['site','SITE CONTROL',Settings2,master],['navigation','NAVIGATION',Settings2,master],['backups','BACKUPS',RotateCcw,master],['analytics','ANALYTICS',BarChart3,master],['recommendations','RECOMMENDATIONS',Activity,master],['intelligence','INTELLIGENCE',Brain,master],['system','SYSTEM',Server,master],['audit','AUDIT',Lock,master],['changelog','CHANGELOG',History,master]
  ];
  const kpi = analytics ? [
    ['USERS',analytics.users.total],['ARTICLES',analytics.content.articles],['POSTS',analytics.content.posts],['COMMENTS',analytics.content.comments],['COMMUNITIES',analytics.content.communities],['SERIES',analytics.content.series],['ANALYTICS EVENTS',analytics.engagement.analyticsEvents],['OPEN REPORTS',analytics.engagement.reportsOpen]
  ] : [];

  return <div className="p-6 max-h-[82vh] overflow-y-auto space-y-5">
    <div className="border-4 border-black bg-black text-white p-5">
      <div className="flex flex-col xl:flex-row xl:items-center xl:justify-between gap-4">
        <div><div className="flex items-center gap-3"><Shield className="w-7 h-7"/><div><h2 className="font-display font-black text-2xl uppercase">OFFSCRPT MASTER CONTROL</h2><p className="font-mono text-[10px] text-neutral-300">Firestore-authoritative controls · security rules enforced · live site-config synchronization</p></div></div></div>
        <div className="flex gap-2"><div className="border-2 border-white px-3 py-2 font-mono text-[9px]">ACTOR: {auth.currentUser?.email || 'unknown'}</div><button onClick={()=>void loadCore()} className="border-2 border-white px-3 py-2 font-mono text-[10px] font-black">REFRESH CLOUD</button></div>
      </div>
    </div>

    <div className="flex flex-wrap gap-2">{tabs.filter(t=>t[3]).map(([key,label,Icon])=><button key={key} onClick={()=>setSection(key)} className={pill(section===key)}><Icon className="inline w-3 h-3 mr-1"/>{label}</button>)}</div>
    {notice && <div className="border-2 border-black bg-neutral-100 px-3 py-2 font-mono text-[10px] font-black">{notice}</div>}
    {cloudErrors.length > 0 && <div className="border-2 border-red-600 bg-red-50 p-3 font-mono text-[10px]"><div className="font-black">CLOUD DIAGNOSTICS — {cloudErrors.length} FAILED OPERATION(S)</div>{cloudErrors.slice(0,12).map((e,i)=><div key={i} className="mt-1">{e}</div>)}</div>}
    {loading && <div className="border-2 border-black p-3 font-mono text-xs">LOADING CLOUD DATA…</div>}

    {!loading && <>
      {section==='dashboard' && <div className="grid md:grid-cols-2 xl:grid-cols-4 gap-3">
        <div className="border-4 border-black p-4"><div className="font-mono text-[9px]">MASTER ACCESS</div><div className="font-display text-xl font-black mt-1">{master?'AUTHORIZED':'STAFF'}</div></div>
        <div className="border-4 border-black p-4"><div className="font-mono text-[9px]">ARTICLES</div><div className="font-display text-3xl font-black mt-1">{articles.length}</div></div>
        <div className="border-4 border-black p-4"><div className="font-mono text-[9px]">USERS</div><div className="font-display text-3xl font-black mt-1">{users.length}</div></div>
        <div className="border-4 border-black p-4"><div className="font-mono text-[9px]">OPEN REPORTS</div><div className="font-display text-3xl font-black mt-1">{openReports.length}</div></div>
      </div>}

      {section==='access' && <div className="space-y-4">
        <div className="border-2 border-black p-4 space-y-3"><h3 className="font-display font-black uppercase">MASTER ADMIN ALLOWLIST</h3><div className="grid md:grid-cols-2 gap-2"><div className="flex gap-2"><input value={emailGrant} onChange={e=>setEmailGrant(e.target.value)} placeholder="admin@example.com" className="flex-1 border-2 border-black p-2 font-mono text-xs"/><button onClick={async()=>{try{await grantMasterAdminByEmail(emailGrant);setEmailGrant('');await loadCore();msg('Master admin email grant written to Firestore.')}catch(e:any){msg(e?.message||'Grant failed.','error')}}} className={pill(false)}>GRANT EMAIL</button></div><div className="flex gap-2"><input value={uidGrant} onChange={e=>setUidGrant(e.target.value)} placeholder="Firebase UID" className="flex-1 border-2 border-black p-2 font-mono text-xs"/><button onClick={async()=>{try{await grantMasterAdminByUid(uidGrant);setUidGrant('');await loadCore();msg('Master admin UID grant written to Firestore.')}catch(e:any){msg(e?.message||'Grant failed.','error')}}} className={pill(false)}>GRANT UID</button></div></div></div>
        <div className="space-y-2">{admins.map(a=><div key={`${a.source}-${a.email||a.uid}`} className="border-2 border-black p-3 flex flex-wrap items-center justify-between gap-3"><div><div className="font-display font-black">{a.email||a.uid}</div><div className="font-mono text-[9px]">{a.source.toUpperCase()} · {a.enabled===false?'DISABLED':'ENABLED'}</div></div><button onClick={async()=>{try{await revokeMasterAdmin(a);await loadCore();msg('Master access revoked in Firestore.')}catch(e:any){msg(e?.message||'Revoke failed.','error')}}} className={danger}>REVOKE</button></div>)}{!admins.length&&<div className="border-2 border-dashed border-black p-6 font-mono text-xs">No additional master entries. Bootstrap master emails remain protected.</div>}</div>
      </div>}

      {section==='users' && <div className="space-y-3"><div className="flex gap-2"><Search className="w-5 h-5 mt-2"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search username, name, email, UID…" className="flex-1 border-2 border-black p-2 font-mono text-xs"/></div>{filteredUsers.slice(0,250).map(u=><div key={u.uid} className="border-2 border-black p-3"><div className="flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">@{u.username || 'unknown'} · {u.displayName || 'Unnamed'}</div><div className="font-mono text-[9px]">{u.uid} · {u.email||'no email'} · role={u.role||'Member'} · {u.isVerified?'VERIFIED':'UNVERIFIED'}</div></div><div className="flex flex-wrap gap-2"><button onClick={()=>{setEditingUser(u);setUserPatch({username:u.username||'',displayName:u.displayName||'',bio:u.bio||'',photoURL:u.photoURL||'',coverImageUrl:u.coverImageUrl||'',websiteUrl:u.websiteUrl||'',location:u.location||'',socialX:u.socialX||'',socialGithub:u.socialGithub||'',socialTelegram:u.socialTelegram||'',socialInstagram:u.socialInstagram||'',isVerified:!!u.isVerified,isBlocked:!!u.isBlocked,isSuspended:!!u.isSuspended,suspensionUntil:u.suspensionUntil||null,restrictCommenting:!!u.restrictCommenting,restrictPosting:!!u.restrictPosting,restrictCommunities:!!u.restrictCommunities,restrictReactions:!!u.restrictReactions,restrictFollowing:!!u.restrictFollowing,moderatorNote:u.moderatorNote||'',warningCount:Number(u.warningCount||0)});}} className={pill(false)}>MODERATE</button><button onClick={()=>void toggleVerification(u)} className={pill(false)}>{u.isVerified?'UNVERIFY':'VERIFY'}</button><button onClick={async()=>{try{await promoteModeratorByUid(u.uid);await loadCore();msg(`@${u.username} promoted to moderator.`)}catch(e:any){msg(e?.message||'Moderator promotion failed.','error')}}} className={pill(false)}>MODERATOR</button><button onClick={async()=>{try{await grantMasterAdminByUid(u.uid);await loadCore();msg(`@${u.username} promoted to master admin.`)}catch(e:any){msg(e?.message||'Master promotion failed.','error')}}} className={pill(false)}>MASTER ADMIN</button><button onClick={()=>void removeUser(u)} className={danger}>DELETE PROFILE</button></div></div></div>)}{!filteredUsers.length&&<div className="border-2 border-dashed border-black p-8 font-mono text-xs">No users match this search.</div>}</div>}

      {section==='posts' && <div className="space-y-3"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Filter posts…" className="w-full border-2 border-black p-2 font-mono text-xs"/>{filteredPosts.slice(0,300).map(p=>{const blog=(p as any).postType==='blog'||(p as any).type==='blog';const promoted=Boolean((p as any).promotedToArticleSlug);return <div key={`${p.sourceType}-${p.communityId||''}-${p.id}`} className="border-2 border-black p-3 flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">{p.title||'(untitled)'}</div><div className="font-mono text-[9px]">{p.sourceType} · @{p.authorUsername} · {p.communitySlug||'root'} · {p.isFeatured?'FEATURED ':''}{p.isPinned?'PINNED ':''}{p.isLocked?'LOCKED':''}</div></div><div className="flex flex-wrap gap-2"><button className={pill(false)} onClick={()=>{const title=prompt('Title',p.title||'');if(title===null)return;const content=prompt('Content',p.content||'');if(content===null)return;const task=p.sourceType==='root'?adminUpdateRootPost(p.id,title,content):p.communityId?adminUpdateCommunityPost(p.communityId,p.id,title,content):Promise.reject(new Error('Community ID missing.'));void task.then(()=>loadCore()).then(()=>msg('Post updated in Firestore.')).catch((e:any)=>msg(e?.message||'Edit failed.','error'));}}>EDIT</button><button className={pill(false)} onClick={()=>{if(p.sourceType==='root')return void adminSetRootPostFeatured(p.id,!p.isFeatured).then(()=>loadCore()).then(()=>msg('Feature state updated.')).catch((e:any)=>msg(e?.message||'Feature failed.','error'));if(p.communityId)void adminSetCommunityPostFeatured(p.communityId,p.id,!p.isFeatured).then(()=>loadCore()).then(()=>msg('Feature state updated.')).catch((e:any)=>msg(e?.message||'Feature failed.','error'));}}>{p.isFeatured?'UNFEATURE':'FEATURE'}</button><button className={pill(false)} onClick={()=>{if(p.sourceType==='root')return void adminSetRootPostModeration(p.id,{isPinned:!Boolean(p.isPinned)}).then(()=>loadCore()).then(()=>msg('Pin state updated.')).catch((e:any)=>msg(e?.message||'Pin failed.','error'));if(p.communityId)void adminSetCommunityPostModeration(p.communityId,p.id,{isPinned:!Boolean(p.isPinned)}).then(()=>loadCore()).then(()=>msg('Pin state updated.')).catch((e:any)=>msg(e?.message||'Pin failed.','error'));}}>{p.isPinned?'UNPIN':'PIN'}</button><button className={pill(false)} onClick={()=>{if(p.sourceType==='root')return void adminSetRootPostModeration(p.id,{isLocked:!Boolean(p.isLocked)}).then(()=>loadCore()).then(()=>msg('Post lock state updated.')).catch((e:any)=>msg(e?.message||'Lock failed.','error'));if(p.communityId)void adminSetCommunityPostModeration(p.communityId,p.id,{isLocked:!Boolean(p.isLocked)}).then(()=>loadCore()).then(()=>msg('Post lock state updated.')).catch((e:any)=>msg(e?.message||'Lock failed.','error'));}}>{p.isLocked?'UNLOCK POST':'LOCK POST'}</button>{p.sourceType==='community'&&p.communityId&&<button className={pill(false)} onClick={()=>void adminSetCommunityPostModeration(p.communityId!,p.id,{isLocked:!Boolean(p.isLocked)}).then(()=>loadCore()).then(()=>msg('Lock state updated.')).catch((e:any)=>msg(e?.message||'Lock failed.','error'))}>{p.isLocked?'UNLOCK':'LOCK'}</button>}{blog&&(p as any).editReviewStatus==='pending'&&<button className={pill(false)} onClick={()=>void approvePublicBlogEdit(p.id,p.communityId,(p as any).promotedToArticleSlug).then(()=>loadCore()).then(()=>msg('Blog edit approved.')).catch((e:any)=>msg(e?.message||'Approve failed.','error'))}>APPROVE EDIT</button>}{blog&&promoted&&<button className={pill(false)} onClick={()=>void unpublishMainArticle({...p,slug:(p as any).promotedToArticleSlug} as any).then(()=>loadCore()).then(()=>msg('Main publication unpublished.')).catch((e:any)=>msg(e?.message||'Unpublish failed.','error'))}>UNPUBLISH MAIN</button>}{blog&&!promoted&&<button className={pill(false)} onClick={()=>void promoteCommunityBlogToMain(p as any,true).then(()=>loadCore()).then(()=>msg('Blog promoted to main publication.')).catch((e:any)=>msg(e?.message||'Promotion failed.','error'))}>PUBLISH ON MAIN</button>}<button className={danger} onClick={()=>{if(!confirm('Delete this post?'))return;const task=p.sourceType==='root'?adminDeleteRootPost(p.id):p.communityId?adminDeleteCommunityPost(p.communityId,p.id):Promise.reject(new Error('Community ID missing.'));void task.then(()=>loadCore()).then(()=>msg('Post deleted from Firestore.')).catch((e:any)=>msg(e?.message||'Delete failed.','error'));}}>DELETE</button></div></div>})}</div>}

      {section==='communities' && <div className="space-y-3"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Filter communities…" className="w-full border-2 border-black p-2 font-mono text-xs"/>{communities.slice(0,250).filter(c=>!search.trim()||`${c.name} ${c.slug} ${c.description}`.toLowerCase().includes(search.toLowerCase())).map(c=><div key={c.id} className="border-2 border-black p-3 flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">c/{c.slug}</div><div className="font-mono text-[9px]">{c.name} · {c.membersCount} members · {c.postsCount} posts · {c.isPrivate?'PRIVATE ':''}{c.isLocked?'LOCKED ':''}{c.isArchived?'ARCHIVED':''}</div></div><div className="flex flex-wrap gap-2"><button className={pill(false)} onClick={()=>setEditingCommunity(c)}>EDIT</button><button className={pill(false)} onClick={()=>void adminSetCommunitySettings(c.id,{isLocked:!c.isLocked}).then(()=>loadCore()).then(()=>msg('Community lock state updated.')).catch((e:any)=>msg(e?.message||'Lock failed.','error'))}>{c.isLocked?'UNLOCK':'LOCK'}</button><button className={pill(false)} onClick={()=>void adminSetCommunitySettings(c.id,{isArchived:!c.isArchived}).then(()=>loadCore()).then(()=>msg('Community archive state updated.')).catch((e:any)=>msg(e?.message||'Archive failed.','error'))}>{c.isArchived?'RESTORE':'ARCHIVE'}</button><button className={danger} onClick={()=>{if(!confirm(`Delete c/${c.slug}?`))return;void deleteCommunity(c.id,auth.currentUser!.uid).then(()=>loadCore()).then(()=>msg('Community deleted from Firestore.')).catch((e:any)=>msg(e?.message||'Delete failed.','error'));}}>DELETE</button></div></div>)}</div>}

      {section==='questions' && <div className="space-y-3"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Filter questions…" className="w-full border-2 border-black p-2 font-mono text-xs"/>{questions.filter(q=>!search.trim()||`${q.title} ${q.authorUsername}`.toLowerCase().includes(search.toLowerCase())).map(q=><div key={q.id} className="border-2 border-black p-3 flex justify-between gap-3"><div><div className="font-display font-black">{q.title}</div><div className="font-mono text-[9px]">@{q.authorUsername} · {q.answersCount||0} answers · {q.upvotesCount||0} upvotes</div></div><div className="flex gap-2"><button className={pill(false)} onClick={()=>{const title=prompt('Question title',q.title);if(title===null)return;const details=prompt('Question details',q.details||'');if(details===null)return;void updateQuestion(q.id,q.authorId,title,details).then(()=>loadCore()).then(()=>msg('Question updated in Firestore.')).catch((e:any)=>msg(e?.message||'Question update failed.','error'));}}>EDIT</button><button className={pill(false)} onClick={()=>{void moderateQuestion(q.id,auth.currentUser?.uid||'',{moderationState:q.moderationState==='HIDDEN'?'VISIBLE':'HIDDEN'}).then(()=>loadCore()).then(()=>msg(`Question ${q.moderationState==='HIDDEN'?'restored':'hidden'}.`)).catch((e:any)=>msg(e?.message||'Question moderation failed.','error'));}}>{q.moderationState==='HIDDEN'?'RESTORE':'HIDE'}</button><button className={pill(false)} onClick={()=>{void moderateQuestion(q.id,auth.currentUser?.uid||'',{moderationState:q.moderationState==='LOCKED'?'VISIBLE':'LOCKED'}).then(()=>loadCore()).then(()=>msg(`Question ${q.moderationState==='LOCKED'?'unlocked':'locked'}.`)).catch((e:any)=>msg(e?.message||'Question moderation failed.','error'));}}>{q.moderationState==='LOCKED'?'UNLOCK':'LOCK'}</button><button className={pill(false)} onClick={()=>{const target=prompt('Enter duplicate question ID');if(!target)return;void moderateQuestion(q.id,auth.currentUser?.uid||'',{moderationState:'DUPLICATE',duplicateOf:target}).then(()=>loadCore()).then(()=>msg('Question marked as duplicate.')).catch((e:any)=>msg(e?.message||'Duplicate marking failed.','error'));}}>DUPLICATE</button><button className={pill(false)} onClick={()=>{const target=prompt('Enter target question ID to merge into');if(!target)return;void mergeQuestions(q.id,target,auth.currentUser?.uid||'').then(()=>loadCore()).then(()=>msg('Question merged into the selected target.')).catch((e:any)=>msg(e?.message||'Question merge failed.','error'));}}>MERGE</button><button className={danger} onClick={()=>{if(!confirm('Delete this question?'))return;void deleteQuestion(q.id,auth.currentUser?.uid||q.authorId).then(()=>loadCore()).then(()=>msg('Question deleted from Firestore.')).catch((e:any)=>msg(e?.message||'Question delete failed.','error'));}}>DELETE</button></div></div>)}</div>}

      {section==='topics' && <div className="space-y-3"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Filter topics…" className="w-full border-2 border-black p-2 font-mono text-xs"/>{topics.filter(t=>!search.trim()||`${t.name} ${t.slug}`.toLowerCase().includes(search.toLowerCase())).map(t=><div key={t.id} className="border-2 border-black p-3 flex justify-between gap-3"><div><div className="font-display font-black">#{t.name}</div><div className="font-mono text-[9px]">{t.slug} · {t.followersCount||0} followers</div></div><div className="flex gap-2"><button className={pill(false)} onClick={()=>{const name=prompt('Topic name',t.name);if(name===null)return;const description=prompt('Description',t.description||'');if(description===null)return;void updateTopic(t.id,auth.currentUser?.uid||t.createdBy||'',name,description).then(()=>loadCore()).then(()=>msg('Topic updated in Firestore.')).catch((e:any)=>msg(e?.message||'Topic update failed.','error'));}}>EDIT</button><button className={danger} onClick={()=>{if(!confirm('Delete this topic?'))return;void deleteTopic(t.id,auth.currentUser?.uid||t.createdBy||'').then(()=>loadCore()).then(()=>msg('Topic deleted from Firestore.')).catch((e:any)=>msg(e?.message||'Topic delete failed.','error'));}}>DELETE</button></div></div>)}</div>}

      {section==='messages' && <div className="space-y-3"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Filter messages…" className="w-full border-2 border-black p-2 font-mono text-xs"/>{messages.filter(m=>!search.trim()||`${m.senderUsername} ${m.content} ${m.recipientId}`.toLowerCase().includes(search.toLowerCase())).slice(0,300).map(m=><div key={m.id} className="border-2 border-black p-3 flex flex-wrap justify-between gap-3"><div><div className="font-mono text-[9px]">@{m.senderUsername} → {m.recipientId} · {m.createdAt}</div><div className="font-mono text-xs mt-1">{m.content}</div></div><div className="flex gap-2"><button className={pill(false)} onClick={()=>{setEditingMessage(m);setMessageDraft(m.content||'');}}>EDIT</button><button className={danger} onClick={()=>{if(!confirm('Delete this message?'))return;void adminDeleteMessage(m.id).then(()=>loadCore()).then(()=>msg('Message deleted from Firestore.')).catch((e:any)=>msg(e?.message||'Message delete failed.','error'));}}>DELETE</button></div></div>)}</div>}

      {section==='moderators' && <div className="space-y-4"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">SITE MODERATORS</h3><p className="font-mono text-[9px] mt-1">Add/remove site moderators and set their granular permissions.</p><div className="flex gap-2 mt-3"><input id="master-moderator-uid" placeholder="Firebase UID" className="flex-1 border-2 border-black p-2 font-mono text-xs"/><button className={pill(false)} onClick={async()=>{const el=document.getElementById('master-moderator-uid') as HTMLInputElement;const uid=(el?.value||'').trim();if(!uid)return msg('UID is required.','error');const u=users.find(x=>x.uid===uid);if(!u)return msg('Load the target user first.','error');try{await addPlatformModerator(uid,u.username,u.displayName);el.value='';await loadCore();msg(`@${u.username} promoted to moderator.`)}catch(e:any){msg(e?.message||'Moderator add failed.','error')}}}>ADD MODERATOR</button></div></div>{moderators.map(m=><div key={m.uid} className="border-2 border-black p-3 flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">@{m.username||m.displayName}</div><div className="font-mono text-[9px]">{m.uid} · {m.enabled===false?'DISABLED':'ENABLED'}</div></div><div className="flex gap-2"><button className={pill(false)} onClick={()=>void openPermissions(m)}>PERMISSIONS</button><button className={danger} onClick={()=>void revokeModeratorByUid(m.uid).then(()=>loadCore()).then(()=>msg('Moderator revoked.')).catch((e:any)=>msg(e?.message||'Revoke failed.','error'))}>REMOVE</button></div></div>)}</div>}

      {section==='site' && site && <div className="space-y-5"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">QUICK PRODUCTION CONTROLS</h3><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-2 mt-3">{([['maintenanceMode','MAINTENANCE MODE'],['communityEnabled','COMMUNITY ENABLED'],['allowCommunityCreation','COMMUNITY CREATION'],['allowCommunityPosts','COMMUNITY POSTS'],['allowQuestions','QUESTIONS'],['allowTopics','TOPICS'],['allowDirectMessages','DIRECT MESSAGES'],['allowPublicBlogs','PUBLIC SCRPTS'],['allowCommunityBlogs','COMMUNITY SCRPTS'],['allowCommunityDiscussions','DISCUSSIONS'],['showSocialAnnouncement','SOCIAL ANNOUNCEMENT']] as Array<[keyof SiteConfig,string]>).map(([k,l])=><label key={String(k)} className="border-2 border-black p-2 font-mono text-[10px]"><input type="checkbox" checked={Boolean((site as any)[k])} onChange={e=>setSite(x=>x?{...x,[k]:e.target.checked}:x)}/> {l}</label>)}</div><div className="grid md:grid-cols-2 gap-2 mt-3"><input value={site.maintenanceMessage||''} onChange={e=>setSite(x=>x?{...x,maintenanceMessage:e.target.value}:x)} placeholder="Maintenance message" className="border-2 border-black p-2 font-mono text-xs"/><input value={site.socialAnnouncement||''} onChange={e=>setSite(x=>x?{...x,socialAnnouncement:e.target.value}:x)} placeholder="Global social announcement" className="border-2 border-black p-2 font-mono text-xs"/><input value={site.socialAnnouncementLink||''} onChange={e=>setSite(x=>x?{...x,socialAnnouncementLink:e.target.value}:x)} placeholder="Announcement link" className="border-2 border-black p-2 font-mono text-xs"/><select value={site.socialDefaultSort||'new'} onChange={e=>setSite(x=>x?{...x,socialDefaultSort:e.target.value as any}:x)} className="border-2 border-black p-2 font-mono text-xs"><option value="new">NEW</option><option value="hot">HOT</option><option value="top">TOP</option><option value="rising">RISING</option></select></div><div className="grid md:grid-cols-4 gap-2 mt-3">{(['themePrimaryColor','themeSecondaryColor','themeAccentColor','themeSuccessColor'] as const).map(k=><label key={k} className="border-2 border-black p-2 font-mono text-[10px]">{k.toUpperCase()}<input value={(site as any)[k]||''} onChange={e=>setSite(x=>x?{...x,[k]:e.target.value}:x)} className="w-full border-2 border-black p-1 mt-1"/></label>)}</div><div className="grid md:grid-cols-2 gap-2 mt-3"><label className="border-2 border-black p-2 font-mono text-[10px]">CURRENT POSITION LINE<input type="color" value={site.readingProgressPageColor||'#2563EB'} onChange={e=>setSite(x=>x?{...x,readingProgressPageColor:e.target.value}:x)} className="w-full h-9 mt-1"/></label><label className="border-2 border-black p-2 font-mono text-[10px]">PERSISTENT READING LINE<input type="color" value={site.readingProgressPersistentColor||site.themePrimaryColor||'#FFD600'} onChange={e=>setSite(x=>x?{...x,readingProgressPersistentColor:e.target.value}:x)} className="w-full h-9 mt-1"/></label></div><button className={pill(false)} onClick={()=>void saveSiteConfig(site).then(async()=>{if(onSiteConfigRestored)await onSiteConfigRestored();msg('Quick production controls saved to Firestore.')}).catch((e:any)=>msg(e?.message||'Site config save failed.','error'))}>SAVE QUICK CONTROLS</button></div>
        <div className="border-2 border-black p-4 space-y-3"><h3 className="font-display font-black uppercase">POPUP ANNOUNCEMENT</h3><p className="font-mono text-[9px]">Fully cloud-backed announcement system with scheduling, audience targeting, priorities, display modes and account-based dismissal. Publish with a new ID when you want a newly issued announcement to reappear after an older dismissal.</p><label className="font-mono text-[10px] font-black flex items-center gap-2"><input type="checkbox" checked={!!site.popupAnnouncement?.enabled} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),enabled:e.target.checked,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)}/> ENABLE POPUP</label><div className="grid md:grid-cols-2 gap-2"><input value={site.popupAnnouncement?.title||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),title:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} placeholder="Announcement title" className="border-2 border-black p-2 font-mono text-xs"/><select value={site.popupAnnouncement?.type||'info'} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),type:e.target.value as any,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"><option value="info">INFO</option><option value="update">UPDATE</option><option value="warning">WARNING</option><option value="urgent">URGENT</option><option value="maintenance">MAINTENANCE</option><option value="feature">FEATURE</option><option value="bugfix">BUG FIX</option><option value="event">EVENT</option></select><select value={site.popupAnnouncement?.priority||'normal'} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),priority:e.target.value as any,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"><option value="low">LOW</option><option value="normal">NORMAL</option><option value="high">HIGH</option><option value="critical">CRITICAL</option></select><select value={site.popupAnnouncement?.displayMode||'popup'} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),displayMode:e.target.value as any,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"><option value="modal">MODAL</option><option value="popup">POPUP</option><option value="banner">BANNER</option></select><select value={site.popupAnnouncement?.frequency||'until_dismissed'} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),frequency:e.target.value as any,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"><option value="once">ONCE</option><option value="session">ONCE PER SESSION</option><option value="daily">ONCE PER DAY</option><option value="every_visit">EVERY VISIT</option><option value="until_dismissed">UNTIL DISMISSED</option></select><select value={site.popupAnnouncement?.audience||'everyone'} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),audience:e.target.value as any,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"><option value="everyone">EVERYONE</option><option value="signed_in">SIGNED IN</option><option value="guests">GUESTS</option><option value="creators">CREATORS</option><option value="moderators">MODERATORS</option><option value="master_admin">MASTER ADMINS</option></select><select value={site.popupAnnouncement?.targetPage||'all'} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),targetPage:e.target.value as any,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"><option value="all">ALL PAGES</option><option value="home">HOME</option><option value="blog">SCRPT</option><option value="article">ARTICLE</option><option value="social">COMMUNITY</option><option value="explore">EXPLORE</option><option value="series">SERIES</option><option value="creator">CREATOR</option><option value="changelog">CHANGELOG</option></select></div><textarea value={site.popupAnnouncement?.message||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),message:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} placeholder="Announcement message" className="w-full min-h-28 border-2 border-black p-2 font-mono text-xs"/><div className="grid md:grid-cols-2 gap-2"><input type="datetime-local" value={site.popupAnnouncement?.startAt||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),startAt:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"/><input type="datetime-local" value={site.popupAnnouncement?.endAt||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),endAt:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} className="border-2 border-black p-2 font-mono text-xs"/><input value={site.popupAnnouncement?.actionLabel||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),actionLabel:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} placeholder="Primary action label" className="border-2 border-black p-2 font-mono text-xs"/><input value={site.popupAnnouncement?.actionTarget||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),actionTarget:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} placeholder="Primary action target" className="border-2 border-black p-2 font-mono text-xs"/><input value={site.popupAnnouncement?.linkLabel||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),linkLabel:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} placeholder="Secondary link label" className="border-2 border-black p-2 font-mono text-xs"/><input value={site.popupAnnouncement?.linkTarget||''} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),linkTarget:e.target.value,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)} placeholder="Secondary link target" className="border-2 border-black p-2 font-mono text-xs"/></div><label className="font-mono text-[10px] font-black flex items-center gap-2"><input type="checkbox" checked={site.popupAnnouncement?.dismissible!==false} onChange={e=>setSite(x=>x?{...x,popupAnnouncement:{...(x.popupAnnouncement||{enabled:false,title:'',message:''}),dismissible:e.target.checked,id:x.popupAnnouncement?.id||`ann-${Date.now()}`}}:x)}/> ALLOW DISMISS</label><button onClick={()=>{const a=site.popupAnnouncement;const hasEscape=a?.dismissible!==false||Boolean(a?.actionLabel&&a?.actionTarget)||Boolean(a?.linkLabel&&a?.linkTarget);if(a?.enabled&&!hasEscape){msg('This announcement has no way to close: enable ALLOW DISMISS, or set a primary/secondary action button, before publishing. An announcement with none of these would block every targeted visitor with no way to close it.','error');return;}void saveSiteConfig(site).then(async()=>{if(onSiteConfigRestored)await onSiteConfigRestored();msg('Announcement saved to Firestore and synchronized site-wide.');}).catch((e:any)=>msg(e?.message||'Announcement save failed.','error'));}} className={pill(false)}>PUBLISH ANNOUNCEMENT</button></div></div>}


      {section==='navigation' && <div className="space-y-4"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">NAVIGATION BUILDER</h3><p className="font-mono text-[9px] mt-1">Reorder and enable/disable public navigation entries. Saved to siteConfig/global.</p>{([['top',navTop,'TOP TABS'],['menu',navMenu,'MENU TABS']] as const).map(([which,items,title])=><div key={which} className="mt-4"><div className="font-display font-black">{title}</div>{items.map((item:any,index:number)=><div key={item.id} className="border-2 border-black p-2 mt-2 flex items-center gap-2"><div className="flex-1 font-mono text-xs">{item.label} · {item.page}</div><label className="font-mono text-[9px]"><input type="checkbox" checked={item.visible!==false} onChange={e=>{const next=items.map((x:any,i:number)=>i===index?{...x,visible:e.target.checked}:x);which==='top'?setNavTop(next):setNavMenu(next);}}/> VISIBLE</label><button className={pill(false)} onClick={()=>moveNav(which,index,-1)}>↑</button><button className={pill(false)} onClick={()=>moveNav(which,index,1)}>↓</button></div>)}</div>)}<div className="flex gap-2 mt-4"><button className={pill(false)} onClick={()=>{setNavTop(DEFAULT_TOP_NAVIGATION);setNavMenu(DEFAULT_MENU_NAVIGATION)}}>RESET DEFAULTS</button><button className={pill(false)} onClick={()=>void saveNavigation()}>SAVE NAVIGATION</button></div></div></div>}

      {section==='backups' && <div className="space-y-4"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">GLOBAL SETTINGS BACKUP / RESTORE</h3><div className="flex gap-2 mt-3"><input value={backupLabel} onChange={e=>setBackupLabel(e.target.value)} placeholder="Backup label" className="flex-1 border-2 border-black p-2 font-mono text-xs"/><button className={pill(false)} onClick={()=>void createBackup()}>CREATE BACKUP</button></div></div>{backups.map(b=><div key={b.id} className="border-2 border-black p-3 flex justify-between gap-2"><div><div className="font-display font-black">{b.label||'Backup'}</div><div className="font-mono text-[9px]">{b.createdAt?.toDate?.()?.toLocaleString?.()||b.createdAt||''} · {b.createdByEmail||''}</div></div><button className={pill(false)} onClick={async()=>{if(!confirm(`Restore ${b.label||b.id}?`))return;try{const restored=await restoreSiteConfigBackup(b.id);setSite(restored);setControls({...DEFAULT_EMERGENCY_CONTROLS,...restored} as EmergencyControls);setNavTop(restored.topNavigation?.length?restored.topNavigation:DEFAULT_TOP_NAVIGATION);setNavMenu(restored.menuNavigation?.length?restored.menuNavigation:DEFAULT_MENU_NAVIGATION);if(onSiteConfigRestored)await onSiteConfigRestored();msg('Backup restored to Firestore.')}catch(e:any){msg(e?.message||'Restore failed.','error')}}}>RESTORE</button></div>)}{!backups.length&&<div className="border-2 border-dashed border-black p-6 font-mono text-xs">NO BACKUPS.</div>}</div>}

      {section==='content' && <div className="space-y-5">
        <div className="border-2 border-black p-4"><div className="flex items-center justify-between"><h3 className="font-display font-black uppercase">ARTICLES</h3><span className="font-mono text-[9px]">{articles.length} cloud records</span></div><div className="space-y-2 mt-3">{articles.slice(0,250).map(a=><div key={a.slug} className="border-2 border-black p-3"><div className="flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">{a.title}</div><div className="font-mono text-[9px]">{a.slug} · {a.isPublished?'PUBLISHED':'UNPUBLISHED'} · {a.featured?'FEATURED':''} {a.pinned?'· PINNED':''}</div></div><div className="flex flex-wrap gap-2"><button onClick={()=>editArticle(a)} className={pill(false)}>EDIT</button><button onClick={()=>void togglePublished(a)} className={pill(false)}>{a.isPublished?'UNPUBLISH':'PUBLISH'}</button><button onClick={()=>void toggleFeature(a)} className={pill(false)}>{a.featured?'UNFEATURE':'FEATURE'}</button><button onClick={()=>void archiveArticle(a)} className={pill(false)}><Archive className="inline w-3 h-3 mr-1"/>ARCHIVE</button><button onClick={()=>void loadRevisions(a)} className={pill(false)}><History className="inline w-3 h-3 mr-1"/>REVISIONS</button><button onClick={()=>void setArticleCommentsLocked(a.slug,!Boolean((a as any).commentsLocked))} className={pill(false)}>{(a as any).commentsLocked?'UNLOCK COMMENTS':'LOCK COMMENTS'}</button><button onClick={()=>void removeArticle(a)} className={danger}>DELETE</button></div></div></div>)}{!articles.length&&<div className="p-6 font-mono text-xs">No cloud articles returned.</div>}</div></div>
        <div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">POSTS</h3><div className="space-y-2 mt-3">{filteredPosts.slice(0,250).map(p=><div key={`${p.sourceType}-${p.communityId||'root'}-${p.id}`} className="border-2 border-black p-3"><div className="flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">{p.title||'(untitled)'}</div><div className="font-mono text-[9px]">{p.sourceType} · @{p.authorUsername} · {p.communitySlug||'root'} · {p.isFeatured?'FEATURED':''} {p.isPinned?'· PINNED':''} {p.isLocked?'· LOCKED':''}</div></div><div className="flex flex-wrap gap-2">{p.sourceType==='root'?<><button onClick={()=>adminUpdateRootPost(p.id,p.title,p.content).then(()=>{void loadCore();msg('Root post update persisted.')}).catch((e:any)=>msg(e?.message||'Edit failed.','error'))} className={pill(false)}>SAVE CURRENT</button><button onClick={()=>adminSetRootPostFeatured(p.id,!p.isFeatured).then(()=>{void loadCore();msg('Root post feature state updated.')}).catch((e:any)=>msg(e?.message||'Feature failed.','error'))} className={pill(false)}>FEATURE</button><button onClick={()=>setPostCommentsLocked(p.id,!Boolean((p as any).commentsLocked)).then(()=>{void loadCore();msg('Root post comment lock updated in Firestore.')}).catch((e:any)=>msg(e?.message||'Lock failed.','error'))} className={pill(false)}>{(p as any).commentsLocked?'UNLOCK COMMENTS':'LOCK COMMENTS'}</button><button onClick={()=>adminDeleteRootPost(p.id).then(()=>{void loadCore();msg('Root post deleted.')}).catch((e:any)=>msg(e?.message||'Delete failed.','error'))} className={danger}>DELETE</button></>:<><button onClick={()=>{if(!p.communityId)return msg('Community ID missing.','error');return adminSetCommunityPostFeatured(p.communityId,p.id,!p.isFeatured).then(()=>{void loadCore();msg('Community post feature state updated.')}).catch((e:any)=>msg(e?.message||'Feature failed.','error'))}} className={pill(false)}>FEATURE</button><button onClick={()=>{if(!p.communityId)return msg('Community ID missing.','error');return adminSetCommunityPostModeration(p.communityId,p.id,{isLocked:!p.isLocked}).then(()=>{void loadCore();msg('Community post moderation state updated.')}).catch((e:any)=>msg(e?.message||'Lock failed.','error'))}} className={pill(false)}>LOCK</button><button onClick={()=>{if(!p.communityId)return msg('Community ID missing.','error');return adminDeleteCommunityPost(p.communityId,p.id).then(()=>{void loadCore();msg('Community post deleted.')}).catch((e:any)=>msg(e?.message||'Delete failed.','error'))}} className={danger}>DELETE</button></>}</div></div></div>)}</div></div>
        <div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">SERIES CONTROL</h3><div className="grid md:grid-cols-2 gap-2 mt-3">{series.slice(0,100).map((s:any)=><div key={s.id||s.slug} className="border-2 border-black p-3"><div className="flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">{s.title||s.name}</div><div className="font-mono text-[9px]">{s.slug||s.id} · {s.articleCount??0} parts · {s.status||'unknown'} · {s.visibility||'public'}</div></div><div className="flex gap-2"><button onClick={()=>{const title=prompt('Series title',s.title||'');if(title===null)return;const description=prompt('Series description',s.description||'');if(description===null)return;void updateSeries(s.id,{title,description}).then(()=>{void loadCore();msg('Series metadata updated in Firestore.')}).catch((e:any)=>msg(e?.message||'Series update failed.','error'))}} className={pill(false)}>EDIT</button><button onClick={()=>{const next=s.status==='published'?'draft':'published';void updateSeries(s.id,{status:next}).then(()=>{void loadCore();msg(`Series status changed to ${next}.`)}).catch((e:any)=>msg(e?.message||'Series status update failed.','error'))}} className={pill(false)}>{s.status==='published'?'UNPUBLISH':'PUBLISH'}</button><button onClick={()=>{if(!confirm(`Delete series ${s.slug||s.id}?`))return;void deleteSeries(s.id).then(()=>{void loadCore();msg('Series deleted from Firestore.')}).catch((e:any)=>msg(e?.message||'Series delete failed.','error'))}} className={danger}>DELETE</button></div></div></div>)}</div></div>
        <div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">COMMUNITY CONTROL</h3><div className="grid md:grid-cols-2 gap-2 mt-3">{communities.slice(0,100).map(c=><div key={c.id} className="border-2 border-black p-3"><div className="flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">{c.name}</div><div className="font-mono text-[9px]">{c.slug} · {c.membersCount} members · {c.postsCount} posts · {c.isLocked?'LOCKED':''} {c.isArchived?'· ARCHIVED':''}</div></div><div className="flex gap-2"><button onClick={()=>{void adminSetCommunitySettings(c.id,{isLocked:!c.isLocked}).then(()=>{void loadCore();msg('Community lock state updated.')}).catch((e:any)=>msg(e?.message||'Community lock failed.','error'))}} className={pill(false)}>{c.isLocked?'UNLOCK':'LOCK'}</button><button onClick={()=>{void adminSetCommunitySettings(c.id,{isArchived:!c.isArchived}).then(()=>{void loadCore();msg('Community archive state updated.')}).catch((e:any)=>msg(e?.message||'Community archive failed.','error'))}} className={pill(false)}>{c.isArchived?'RESTORE':'ARCHIVE'}</button><button onClick={()=>{if(!confirm(`Delete community ${c.slug}?`))return;void deleteCommunity(c.id,auth.currentUser!.uid).then(()=>{void loadCore();msg('Community deleted from Firestore.')}).catch((e:any)=>msg(e?.message||'Community delete failed.','error'))}} className={danger}>DELETE</button></div></div></div>)}</div></div>
      </div>}

      {section==='comments' && <div className="space-y-3"><div className="flex justify-between gap-2"><div className="font-display font-black uppercase">RECENT COMMENTS · CLOUD</div><button onClick={()=>void loadComments()} className={pill(false)}><RefreshCw className="inline w-3 h-3 mr-1"/>REFRESH</button></div>{filteredComments.slice(0,200).map(c=><div key={c.path} className="border-2 border-black p-3"><div className="flex flex-wrap justify-between gap-3"><div><div className="font-mono text-[9px]">{c.sourceType.toUpperCase()} · {c.path} · {c.createdAt||''}</div><div className="font-display font-black">@{c.authorUsername||c.authorName||'unknown'}</div><div className="font-mono text-xs mt-1 max-w-3xl">{c.content}</div></div><div className="flex flex-wrap gap-2 items-start"><button onClick={()=>setCommentTarget(c)} className={pill(false)}>{c.isHidden?'RESTORE':'HIDE'}</button><button onClick={async()=>{try{if(c.sourceType==='article')await deleteArticleCommentAsMaster(c.articleSlug!,c.id);else if(c.sourceType==='community_post')await deleteCommunityPostCommentAsMaster(c.communityId!,c.postId!,c.id);else await deletePostCommentAsMaster(c.postId!,c.id);await loadComments();msg('Comment deletion state synced.')}catch(e:any){msg(e?.message||'Comment delete failed.','error')}}} className={danger}>DELETE</button></div></div></div>)}{!filteredComments.length&&<div className="border-2 border-dashed border-black p-8 font-mono text-xs">No comments returned from Firestore.</div>}</div>}

      {section==='reports' && <div className="space-y-5">
        <div className="space-y-3"><div className="font-display font-black uppercase">REPORTS CENTER · {openReports.length} ACTIVE</div>{openReports.map(r=><div key={r.id} className="border-2 border-black p-4"><div className="flex flex-wrap justify-between gap-2"><div><div className="font-mono text-[9px]">REPORT {r.id} · {r.createdAt} · {r.status}</div><div className="font-display font-black">{r.targetType} · {r.targetId}</div><div className="font-mono text-xs mt-1">REPORTER: {r.reporterUsername||r.reporterId} · REASON: {r.reason}</div></div><div className="flex flex-wrap gap-2"><button onClick={()=>void runReportStatus(r,'under_review')} className={pill(false)}>UNDER REVIEW</button><button onClick={()=>void runReportStatus(r,'action_taken')} className={pill(false)}>ACTION TAKEN</button><button onClick={()=>void runReportStatus(r,'resolved')} className={pill(false)}>RESOLVE</button><button onClick={()=>void runReportStatus(r,'dismissed')} className={danger}>DISMISS</button></div></div></div>)}{!openReports.length&&<div className="border-2 border-dashed border-black p-8 font-mono text-xs">NO ACTIVE REPORTS.</div>}<textarea value={reportResponse} onChange={e=>setReportResponse(e.target.value)} placeholder="Optional moderator resolution note applied to the next report action" className="w-full border-2 border-black p-3 font-mono text-xs min-h-20"/></div>
        <div className="border-2 border-black p-4"><div className="flex items-center justify-between"><div><h3 className="font-display font-black uppercase">SITE PROBLEM REPORTS</h3><p className="font-mono text-[9px]">Bug reports submitted from the public changelog.</p></div><button onClick={()=>void getProblemReportsForAdmin().then(setProblemReports).catch((e:any)=>msg(e?.message||'Problem reports load failed.','error'))} className={pill(false)}>REFRESH</button></div><div className="space-y-2 mt-3">{problemReports.map(r=><div key={r.id} className="border-2 border-black p-3"><div className="flex flex-wrap justify-between gap-2"><div><div className="font-display font-black uppercase">{r.title}</div><div className="font-mono text-[9px]">{r.targetPage||'site'} · {r.reporterHandle ? '@'+r.reporterHandle : 'private reporter'} · {r.createdAt}</div></div><select value={r.status} onChange={e=>{const status=e.target.value as ProblemStatus;void updateProblemReport(r.id,{status,adminComment:r.adminComment||''}).then(()=>getProblemReportsForAdmin()).then(setProblemReports).catch((e:any)=>msg(e?.message||'Problem status update failed.','error'));}} className="border-2 border-black p-1 font-mono text-[9px] font-black"><option value="NOTED">NOTED</option><option value="IN_REVIEW">IN REVIEW</option><option value="FIXED">FIXED</option><option value="CLOSED">CLOSED</option></select></div><p className="font-mono text-xs mt-2 whitespace-pre-wrap">{r.description}</p><textarea value={problemCommentDrafts[r.id] ?? r.adminComment ?? ''} onChange={e=>setProblemCommentDrafts(x=>({...x,[r.id]:e.target.value}))} placeholder="Admin comment / resolution" className="w-full min-h-20 border-2 border-black p-2 mt-2 font-mono text-xs"/><button onClick={()=>void updateProblemReport(r.id,{status:r.status,adminComment:problemCommentDrafts[r.id] ?? r.adminComment ?? ''}).then(()=>getProblemReportsForAdmin()).then(setProblemReports).then(()=>msg('Problem report updated in Firestore.')).catch((e:any)=>msg(e?.message||'Problem report update failed.','error'))} className={`${pill(false)} mt-2`}>SAVE RESPONSE</button></div>)}{!problemReports.length&&<div className="border-2 border-dashed border-black p-6 font-mono text-xs">NO USER PROBLEM REPORTS.</div>}</div></div>
      </div>}

      {section==='moderation' && <div className="space-y-4"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">GRANULAR MODERATOR PERMISSION MATRIX</h3><p className="font-mono text-[9px] mt-1">Permissions are persisted in siteModerators/{'{uid}'} and enforced by Firestore rules for protected operations.</p><div className="space-y-2 mt-3">{moderators.map(m=><div key={m.uid} className="border-2 border-black p-3 flex flex-wrap items-center justify-between gap-3"><div><div className="font-display font-black">@{m.username||m.displayName}</div><div className="font-mono text-[9px]">{m.uid} · {m.enabled===false?'DISABLED':'ENABLED'}</div></div><div className="flex gap-2"><button onClick={()=>void openPermissions(m)} className={pill(false)}>EDIT PERMISSIONS</button><button onClick={async()=>{try{await revokeModeratorByUid(m.uid);await loadCore();msg(`@${m.username} moderator access revoked.`)}catch(e:any){msg(e?.message||'Revoke failed.','error')}}} className={danger}>REVOKE</button></div></div>)}</div></div><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">PERMISSION KEYS</h3><div className="grid md:grid-cols-3 gap-2 mt-3">{['manageReports','moderatePosts','moderateComments','manageUsers','editArticles','deleteArticles','viewAnalytics'].map(k=><div key={k} className="border-2 border-black p-3 font-mono text-[10px]">{k}</div>)}</div></div></div>}

      {section==='config' && <div className="space-y-5"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">EMERGENCY CONTROLS — SECURITY RULE ENFORCED</h3><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-2 mt-4">{([['emergencyAdminLock','EMERGENCY ADMIN LOCK'],['maintenanceMode','MAINTENANCE'],['readOnlyMode','READ-ONLY'],['registrationsEnabled','REGISTRATIONS'],['commentsEnabled','COMMENTS'],['postingEnabled','POSTING'],['reactionsEnabled','REACTIONS'],['followingEnabled','FOLLOWING'],['communityCreationEnabled','COMMUNITY CREATION'],['communityPostsEnabled','COMMUNITY POSTS'],['questionsEnabled','QUESTIONS'],['topicsEnabled','TOPICS'],['directMessagesEnabled','MESSAGES'],['publicBlogsEnabled','PUBLIC SCRPTS'],['communityBlogsEnabled','COMMUNITY SCRPTS'],['communityDiscussionsEnabled','DISCUSSIONS'],['uploadsEnabled','UPLOADS']] as Array<[keyof EmergencyControls,string]>).map(([key,label])=><label key={String(key)} className="border-2 border-black p-3 flex items-center gap-3 font-mono text-[10px] font-black"><input type="checkbox" checked={!!(controls as any)[key]} disabled={saving} onChange={e=>void saveEmergency({[key]:e.target.checked} as any)}/>{label}</label>)}</div><textarea value={controls.maintenanceMessage||''} onChange={e=>setControls(c=>({...c,maintenanceMessage:e.target.value}))} className="w-full border-2 border-black p-3 mt-3 font-mono text-xs"/><button onClick={()=>void saveEmergency({maintenanceMessage:controls.maintenanceMessage})} className={pill(false)}><Save className="inline w-3 h-3 mr-1"/>SAVE MESSAGE</button></div>{site&&<div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">GLOBAL FIRESTORE SITE CONFIG</h3><textarea defaultValue={JSON.stringify(site,null,2)} key={JSON.stringify(site)} id="master-site-json" className="w-full min-h-[380px] border-2 border-black p-3 mt-3 font-mono text-[10px]"/><button onClick={async()=>{try{const el=document.getElementById('master-site-json') as HTMLTextAreaElement;const parsed=JSON.parse(el.value);await saveSiteConfig(parsed);setSite(parsed);if(onSiteConfigRestored)await onSiteConfigRestored();msg('Global configuration saved to Firestore.')}catch(e:any){msg(e?.message||'Invalid config JSON or save failed.','error')}}} className={pill(false)}>SAVE GLOBAL CONFIG</button></div>}</div>}

      {section==='analytics' && <div className="space-y-4"><div className="flex flex-wrap justify-between gap-2"><div className="font-mono text-[9px]">LIVE PLATFORM ANALYTICS · Firestore aggregates · refreshed automatically every 30s while this tab is open.</div><button onClick={()=>void runAnalytics()} className={pill(false)}><RefreshCw className="inline w-3 h-3 mr-1"/>REFRESH REAL DATA</button></div>{analytics?<><div className="grid md:grid-cols-2 xl:grid-cols-5 gap-3">{[["USERS",analytics.users.total],["ARTICLES",analytics.content.articles],["POSTS",analytics.content.posts],["COMMENTS",analytics.content.comments],["COMMUNITIES",analytics.content.communities],["UNIQUE READERS",analytics.engagement.uniqueReaders],["COMPLETED SESSIONS",analytics.engagement.completedSessions],["READING MINUTES",Math.round(analytics.engagement.totalReadingTimeMs/60000)],["AVG SCROLL %",analytics.engagement.averageScrollDepth],["REACTIONS",analytics.engagement.reactions],["BOOKMARKS",analytics.engagement.bookmarks],["SHARES",analytics.engagement.shares],["OPEN REPORTS",analytics.engagement.reportsOpen],["ANALYTICS EVENTS",analytics.engagement.analyticsEvents]].map(([l,n])=><div key={String(l)} className="border-4 border-black p-4"><div className="font-mono text-[9px]">{l}</div><div className="font-display font-black text-3xl mt-1">{n}</div></div>)}</div><div><div className="font-display font-black uppercase mb-2">TIME WINDOWS</div><div className="grid md:grid-cols-4 gap-3">{Object.entries(analytics.engagement.periods).map(([period,m])=><div key={period} className="border-2 border-black p-4"><div className="font-display font-black">{period}</div><div className="font-mono text-[9px] mt-2">SESSIONS {m.sessions}</div><div className="font-mono text-[9px]">UNIQUE READERS {m.uniqueReaders}</div><div className="font-mono text-[9px]">COMPLETED {m.completedSessions}</div><div className="font-mono text-[9px]">SHARES {m.shares}</div><div className="font-mono text-[9px]">READ MIN {Math.round(m.readingTimeMs/60000)}</div><div className="font-mono text-[9px]">SCROLL {m.averageScrollDepth}%</div></div>)}</div></div><div><div className="font-display font-black uppercase mb-2">TOP ARTICLES · REAL CLOUD DATA</div><div className="space-y-2">{analytics.articles.slice(0,20).map(a=><div key={a.slug} className="border-2 border-black p-3 grid lg:grid-cols-[2fr_1fr_1fr_1fr_1fr_1fr] gap-2 items-center"><div><div className="font-display font-black">{a.title}</div><div className="font-mono text-[9px]">{a.slug} · @{a.authorUsername||'unknown'}</div></div><div className="font-mono text-[9px]">SESSIONS {a.sessions}</div><div className="font-mono text-[9px]">UNIQUE {a.uniqueReaders}</div><div className="font-mono text-[9px]">COMPLETE {a.completionRate}%</div><div className="font-mono text-[9px]">READ {Math.round(a.readingTimeMs/60000)}m</div><div className="font-mono text-[9px]">SCROLL {a.averageScrollDepth}%</div></div>)}{!analytics.articles.length&&<div className="border-2 border-dashed border-black p-6 font-mono text-xs">No article analytics found in Firestore.</div>}</div></div><div><div className="font-display font-black uppercase mb-2">CREATOR COMPARISON · AGGREGATE ONLY</div><div className="space-y-2">{analytics.creators.slice(0,20).map(c=><div key={c.uid} className="border-2 border-black p-3 grid lg:grid-cols-[2fr_1fr_1fr_1fr_1fr_1fr] gap-2 items-center"><div><div className="font-display font-black">@{c.username||c.name||'unknown'}</div><div className="font-mono text-[9px]">{c.articles} article(s)</div></div><div className="font-mono text-[9px]">SESSIONS {c.sessions}</div><div className="font-mono text-[9px]">UNIQUE {c.uniqueReaders}</div><div className="font-mono text-[9px]">COMPLETE {c.completionRate}%</div><div className="font-mono text-[9px]">READ {Math.round(c.readingTimeMs/60000)}m</div><div className="font-mono text-[9px]">SHARES {c.shares}</div></div>)}{!analytics.creators.length&&<div className="border-2 border-dashed border-black p-6 font-mono text-xs">No creator analytics found in Firestore.</div>}</div></div><div className="border-2 border-black p-4 font-mono text-[10px]">NEW USERS: {analytics.users.new7d} (7D) · {analytics.users.new30d} (30D) · MEASURED: {new Date(analytics.measuredAt).toLocaleString()} · Reader identities are aggregated and are not exposed to creator dashboards.</div></>:<div className="border-2 border-dashed border-black p-8 font-mono text-xs">RUN REFRESH REAL DATA.</div>}</div>}

      {section==='recommendations' && <div className="space-y-4"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">RECOMMENDATION SOURCE HEALTH</h3><p className="font-mono text-[10px] mt-1">This does not fabricate recommendation records. It verifies cloud source inventory used by the recommendation engine.</p><button onClick={()=>void runRecommendations()} className={`${pill(false)} mt-3`}>CHECK FIRESTORE SOURCES</button></div>{recommendationHealth&&<><div className="grid md:grid-cols-3 gap-3">{Object.entries(recommendationHealth.sourceCounts).map(([k,v])=><div key={k} className="border-4 border-black p-4"><div className="font-mono text-[9px]">{k.toUpperCase()}</div><div className="font-display text-3xl font-black">{v}</div></div>)}</div><div className="border-2 border-black p-4 font-mono text-xs">{recommendationHealth.note}</div><div className="space-y-2">{recommendationHealth.topCloudArticles.map(x=><div key={x.slug} className="border-2 border-black p-3"><span className="font-display font-black">{x.title}</span><span className="font-mono text-[9px]"> · {x.slug} · {x.views} views</span></div>)}</div></>}</div>}

      {section==='intelligence' && <div className="space-y-4">
        <div className="border-2 border-black p-4 bg-neutral-50">
          <div className="flex items-center justify-between gap-3 flex-wrap">
            <div><h3 className="font-display font-black uppercase">KNOWLEDGE ENGINE · V84</h3><p className="font-mono text-[9px] mt-1">Canonical content inventory and semantic-provider readiness. Counts are source inventory, not fabricated vector-index counts.</p></div>
            <div className="border-2 border-black bg-white px-3 py-2 font-mono text-[9px] font-black">SCHEMA 84</div>
          </div>
          <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3 mt-4">
            <div className="border-2 border-black p-3"><div className="font-mono text-[8px]">ARTICLES</div><div className="font-display font-black text-2xl">{articles.filter(a=>a.isPublished!==false&&a.mainPublicationStatus!=='unpublished').length}</div></div>
            <div className="border-2 border-black p-3"><div className="font-mono text-[8px]">POSTS</div><div className="font-display font-black text-2xl">{posts.filter(p=>(p as any).isPublished!==false&&(p as any).mainPublicationStatus!=='unpublished').length}</div></div>
            <div className="border-2 border-black p-3"><div className="font-mono text-[8px]">QUESTIONS</div><div className="font-display font-black text-2xl">{questions.length}</div></div>
            <div className="border-2 border-black p-3"><div className="font-mono text-[8px]">SERIES</div><div className="font-display font-black text-2xl">{series.filter((x:any)=>x.visibility!=='private'&&x.status!=='archived').length}</div></div>
          </div>
          <div className="grid md:grid-cols-2 gap-3 mt-4">
            <div className="border-2 border-black p-3"><div className="font-mono text-[8px] font-black">INDEX PIPELINE</div><div className="font-display font-black mt-1">NORMALIZE → CHUNK → EMBED → INDEX</div><div className="font-mono text-[8px] mt-2 text-neutral-600">Firestore remains canonical. External embedding/vector services are optional and configured server-side.</div></div>
            <div className="border-2 border-black p-3"><div className="font-mono text-[8px] font-black">SEMANTIC PROVIDER</div><div className="font-display font-black mt-1">{(typeof import.meta!=='undefined' && (import.meta as any).env?.VITE_OFFSCRPT_VECTOR_ENDPOINT)?'CONFIGURED':'NOT CONFIGURED'}</div><div className="font-mono text-[8px] mt-2 text-neutral-600">No external provider is claimed unless the deployment actually supplies its endpoints.</div></div>
          </div>
        </div>

        <div className="border-2 border-black p-4 space-y-4">
          <div>
            <h3 className="font-display font-black uppercase">AI CONTROL · APPEARANCE</h3>
            <p className="font-mono text-[9px] mt-1">Centralized AI theme. Changes are stored in siteConfig/global and consumed live by AI surfaces through shared tokens.</p>
          </div>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
            {AI_THEME_KEYS.map(key => (
              <label key={String(key)} className="border-2 border-black p-3 bg-white block">
                <div className="font-mono text-[9px] font-black uppercase">{String(key).replace(/[A-Z]/g, m => ` ${m}`)}</div>
                <div className="flex gap-2 mt-2">
                  <input type="color" value={/^#[0-9a-fA-F]{6}$/.test(String(aiThemeDraft[key])) ? String(aiThemeDraft[key]) : "#000000"} onChange={e=>updateAIThemeDraft(key,e.target.value)} className="w-12 h-10 border-2 border-black shrink-0" aria-label={`${String(key)} color`}/>
                  <input value={String(aiThemeDraft[key])} onChange={e=>updateAIThemeDraft(key,e.target.value)} className="min-w-0 flex-1 border-2 border-black px-2 font-mono text-[10px] uppercase" maxLength={7} spellCheck={false}/>
                </div>
              </label>
            ))}
          </div>
          <div className="flex flex-wrap items-end gap-3 border-2 border-black p-3">
            <label className="font-mono text-[9px] font-black uppercase">Preset
              <select onChange={e=>applyAIPreset(e.target.value)} defaultValue="" className="block border-2 border-black bg-white px-3 py-2 mt-1 font-mono text-[10px]">
                <option value="">CUSTOM</option><option>DEFAULT</option><option>NEON</option><option>MONOCHROME</option><option>BLUE</option><option>PURPLE</option><option>GREEN</option><option>RED</option><option>AMBER</option>
              </select>
            </label>
            <div className="font-mono text-[9px] font-black uppercase">Contrast<br/><span className={contrastRatio(aiThemeDraft.text, aiThemeDraft.background) >= 4.5 ? 'text-green-700' : contrastRatio(aiThemeDraft.text, aiThemeDraft.background) >= 3 ? 'text-amber-700' : 'text-red-700'}>{contrastRatio(aiThemeDraft.text, aiThemeDraft.background).toFixed(2)}:1 · {contrastRatio(aiThemeDraft.text, aiThemeDraft.background) >= 4.5 ? 'GOOD' : contrastRatio(aiThemeDraft.text, aiThemeDraft.background) >= 3 ? 'LOW' : 'POOR'}</span></div>
            <div className="font-mono text-[9px] font-black uppercase">Button<br/><span className={contrastRatio(aiThemeDraft.buttonText, aiThemeDraft.primary) >= 4.5 ? 'text-green-700' : contrastRatio(aiThemeDraft.buttonText, aiThemeDraft.primary) >= 3 ? 'text-amber-700' : 'text-red-700'}>{contrastRatio(aiThemeDraft.buttonText, aiThemeDraft.primary).toFixed(2)}:1</span></div>
            <div className="font-mono text-[9px] font-black uppercase">Assistant<br/><span className={contrastRatio(aiThemeDraft.text, aiThemeDraft.assistantMessage) >= 4.5 ? 'text-green-700' : contrastRatio(aiThemeDraft.text, aiThemeDraft.assistantMessage) >= 3 ? 'text-amber-700' : 'text-red-700'}>{contrastRatio(aiThemeDraft.text, aiThemeDraft.assistantMessage).toFixed(2)}:1</span></div>
          </div>
          <div className="border-2 border-black p-4" style={{
            ['--ai-primary' as any]: aiThemeDraft.primary, ['--ai-secondary' as any]: aiThemeDraft.secondary, ['--ai-accent' as any]: aiThemeDraft.accent,
            ['--ai-background' as any]: aiThemeDraft.background, ['--ai-surface' as any]: aiThemeDraft.surface, ['--ai-border' as any]: aiThemeDraft.border,
            ['--ai-text' as any]: aiThemeDraft.text, ['--ai-muted-text' as any]: aiThemeDraft.mutedText, ['--ai-button-text' as any]: aiThemeDraft.buttonText,
            ['--ai-hover' as any]: aiThemeDraft.hover, ['--ai-active' as any]: aiThemeDraft.active, ['--ai-input-background' as any]: aiThemeDraft.inputBackground,
            ['--ai-input-border' as any]: aiThemeDraft.inputBorder, ['--ai-user-message' as any]: aiThemeDraft.userMessage, ['--ai-assistant-message' as any]: aiThemeDraft.assistantMessage,
            ['--ai-source' as any]: aiThemeDraft.source, ['--ai-link' as any]: aiThemeDraft.link, ['--ai-icon' as any]: aiThemeDraft.icon, ['--ai-header' as any]: aiThemeDraft.header,
          }}>
            <div className="font-mono text-[9px] font-black uppercase mb-2">LIVE PREVIEW</div>
            <div className="ai-themed border-2 border-black bg-white text-black" style={{ ['--ai-primary' as any]: aiThemeDraft.primary, ['--ai-secondary' as any]: aiThemeDraft.secondary, ['--ai-accent' as any]: aiThemeDraft.accent, ['--ai-background' as any]: aiThemeDraft.background, ['--ai-surface' as any]: aiThemeDraft.surface, ['--ai-border' as any]: aiThemeDraft.border, ['--ai-text' as any]: aiThemeDraft.text, ['--ai-muted-text' as any]: aiThemeDraft.mutedText, ['--ai-button-text' as any]: aiThemeDraft.buttonText, ['--ai-hover' as any]: aiThemeDraft.hover, ['--ai-active' as any]: aiThemeDraft.active, ['--ai-input-background' as any]: aiThemeDraft.inputBackground, ['--ai-input-border' as any]: aiThemeDraft.inputBorder, ['--ai-user-message' as any]: aiThemeDraft.userMessage, ['--ai-assistant-message' as any]: aiThemeDraft.assistantMessage, ['--ai-source' as any]: aiThemeDraft.source, ['--ai-link' as any]: aiThemeDraft.link, ['--ai-icon' as any]: aiThemeDraft.icon, ['--ai-header' as any]: aiThemeDraft.header }}>
              <div className="ai-preview-header p-3 border-b-2 border-black font-display font-black uppercase">OFFSCRPT AI <button className="float-right border-2 border-black bg-white px-2 py-1 font-mono text-[8px] font-black">ASK</button></div>
              <div className="p-3 space-y-2"><div className="ai-preview-user border-2 border-black p-2 font-mono text-[9px]">YOU · What is OFFSCRPT?</div><div className="ai-preview-assistant border-2 border-black p-2 text-sm">This is a live preview of your AI theme.</div><div className="ai-preview-source border-2 border-black p-2 font-mono text-[9px]">SOURCE · OFFSCRPT SCRPT</div><input className="w-full border-2 border-black p-2 text-sm" placeholder="Ask OFFSCRPT…"/></div>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button className={pill(false)} onClick={resetAIThemeSettings}>RESET DEFAULTS</button>
            <button className={pill(false)} onClick={cancelAIThemeChanges} disabled={saving}>CANCEL</button>
            <button className={pill(false)} disabled={saving} onClick={()=>void saveAIThemeSettings()}><Save className="inline w-3 h-3 mr-1"/> {saving?'SAVING…':'SAVE AI APPEARANCE'}</button>
            <div className="font-mono text-[8px] text-neutral-500">Saves to Firestore · Master Admin only</div>
          </div>
        </div>
        <div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">V80 INTELLIGENCE CORE · FEATURE FLAGS</h3><p className="font-mono text-[9px] mt-1">Flags are stored in intelligenceConfig/global. Master-only writes; client surfaces subscribe to the same source. AI retrieval is also re-checked server-side by the gateway.</p></div>
        <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-3">{(Object.keys(DEFAULT_INTELLIGENCE_FLAGS) as Array<keyof IntelligenceFeatureFlags>).filter(k=>k!=='updatedAt').map(key=><label key={String(key)} className="border-2 border-black p-4 flex items-start gap-3 font-mono text-[10px] font-black"><input type="checkbox" checked={!!intelligenceFlags[key]} onChange={e=>void saveIntelligenceFlag(key,e.target.checked)} /><span><span className="block uppercase">{String(key).replace(/([A-Z])/g,' $1')}</span><span className="block mt-1 text-[8px] font-normal text-neutral-500">{key==='aiRetrieval'?'Server-enforced emergency switch.':key==='semanticSearch'?'V80 architecture flag; vector backend remains foundation-only.':'Shared platform switch.'}</span></span></label>)}</div>
        <div className="border-2 border-black p-4"><div className="flex justify-between gap-3 items-center"><h3 className="font-display font-black uppercase">ACTIVITY EVENT HEALTH</h3><button onClick={()=>void runActivityHealth()} className={pill(false)}>REFRESH</button></div>{activityHealth?<><div className="grid md:grid-cols-3 gap-2 mt-3"><div className="border-2 border-black p-3"><div className="font-mono text-[8px]">SAMPLED EVENTS</div><div className="font-display text-2xl font-black">{activityHealth.totalEvents}</div></div><div className="border-2 border-black p-3"><div className="font-mono text-[8px]">LAST 24H</div><div className="font-display text-2xl font-black">{activityHealth.recent24h}</div></div><div className="border-2 border-black p-3"><div className="font-mono text-[8px]">LATEST</div><div className="font-mono text-[9px] mt-1">{activityHealth.latestAt||'—'}</div></div></div><div className="font-mono text-[9px] mt-3">{Object.entries(activityHealth.eventTypes).sort((a,b)=>b[1]-a[1]).slice(0,20).map(([k,v])=>`${k}:${v}`).join(' · ')}</div></>:<div className="font-mono text-[9px] mt-2 text-neutral-500">No standardized event sample loaded yet.</div>}</div>
        <div className="border-2 border-black p-4 font-mono text-[10px]"><div>CONFIG PATH: intelligenceConfig/global</div><div>AI RETRIEVAL: {intelligenceFlags.aiRetrieval?'ENABLED':'DISABLED'}</div><div>SEMANTIC SEARCH: {intelligenceFlags.semanticSearch?'ENABLED':'FOUNDATION ONLY'}</div><div>RECOMMENDATIONS: {intelligenceFlags.recommendations?'ENABLED':'DISABLED'}</div></div>
      </div>}

      {section==='commerce' && <CommerceAdminPanel/>}
      {section==='system' && <div className="space-y-4"><div className="grid md:grid-cols-2 gap-3">{health.map(h=><div key={h.name} className="border-2 border-black p-4"><div className="flex items-center justify-between"><div className="font-display font-black uppercase">{h.name}</div>{h.status==='healthy'?<CheckCircle2 className="w-5 h-5"/>:h.status==='degraded'?<AlertTriangle className="w-5 h-5"/>:<XCircle className="w-5 h-5"/>}</div><div className="font-mono text-[9px] mt-2">{h.detail}{h.latencyMs!==undefined?` · ${h.latencyMs}ms`:''}</div></div>)}</div><div className="grid md:grid-cols-2 gap-3"><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">SESSION / SECURITY</h3><div className="font-mono text-[10px] mt-2">UID: {auth.currentUser?.uid||'signed out'}</div><div className="font-mono text-[10px]">EMAIL: {auth.currentUser?.email||'n/a'}</div><div className="font-mono text-[10px]">LAST SIGN-IN: {auth.currentUser?.metadata.lastSignInTime||'n/a'}</div><div className="font-mono text-[10px]">MASTER ACCESS: {master?'YES':'NO'}</div></div><div className="border-2 border-black p-4"><h3 className="font-display font-black uppercase">REALTIME PRESENCE</h3><div className="font-display font-black text-3xl mt-1">{presence?.activeUsers??'—'}</div><div className="font-mono text-[9px]">Unique active users across the presence member collections at last check. Expired heartbeats are excluded.</div></div></div><div className="border-2 border-black p-4 flex items-center justify-between"><div className="font-display font-black">SUMMARY: {health.length ? buildHealthSummary(health).toUpperCase() : 'NOT CHECKED'}</div><button onClick={()=>void runHealth()} className={pill(false)}>RUN REAL CHECKS</button></div></div>}

      {section==='audit' && <div className="space-y-2"><div className="flex justify-between"><div className="font-display font-black uppercase">PRIVILEGED AUDIT LOG</div><button onClick={()=>void loadAudit()} className={pill(false)}>LOAD AUDIT</button></div>{audit.map(a=><div key={a.id} className="border-2 border-black p-3"><div className="font-mono text-[9px] font-black">{a.action} · {a.createdAt||'pending'}</div><div className="font-display font-black">{a.target}</div><div className="font-mono text-[9px]">ACTOR: {a.actorEmail||a.actorId} · RESULT: recorded</div></div>)}{!audit.length&&<div className="border-2 border-dashed border-black p-8 font-mono text-xs">NO AUDIT EVENTS LOADED.</div>}</div>}
    </>}

    {editingUser && <div className="fixed inset-0 z-[400] bg-black/70 p-4 grid place-items-center"><div className="bg-white border-4 border-black w-full max-w-3xl p-5 space-y-4 max-h-[90vh] overflow-y-auto"><div className="flex justify-between"><h3 className="font-display font-black uppercase">USER CONTROL · @{editingUser.username}</h3><button onClick={()=>setEditingUser(null)}>✕</button></div><div className="grid md:grid-cols-2 gap-2"><input value={userPatch.username||''} onChange={e=>setUserPatch((p:any)=>({...p,username:e.target.value.toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,30)}))} placeholder="Unique @handle (leave blank to unclaim)" className="border-2 border-black p-3 font-mono text-xs"/><input value={userPatch.displayName||''} onChange={e=>setUserPatch((p:any)=>({...p,displayName:e.target.value}))} placeholder="Display name" className="border-2 border-black p-3 font-mono text-xs"/><div className="border-2 border-black p-2 space-y-2"><div className="font-mono text-[9px] font-black uppercase">Avatar</div><div className="flex flex-col gap-2"><input value={userPatch.photoURL||''} onChange={e=>setUserPatch((p:any)=>({...p,photoURL:e.target.value}))} placeholder="Avatar URL" className="border-2 border-black p-3 font-mono text-xs"/><MediaUploadButton folder="profile" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" label="UPLOAD AVATAR" compact targetUid={editingUser.uid} cropAspect="1:1" cropShape="circle" outputWidth={800} outputHeight={800} onUploaded={(url)=>setUserPatch((p:any)=>({...p,photoURL:url}))}/></div></div><div className="border-2 border-black p-2 space-y-2"><div className="font-mono text-[9px] font-black uppercase">Cover</div><div className="flex flex-col gap-2"><input value={userPatch.coverImageUrl||''} onChange={e=>setUserPatch((p:any)=>({...p,coverImageUrl:e.target.value}))} placeholder="Cover image URL" className="border-2 border-black p-3 font-mono text-xs"/><MediaUploadButton folder="profile" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" label="UPLOAD COVER" compact targetUid={editingUser.uid} cropAspect="2:1" cropShape="rect" outputWidth={1600} outputHeight={800} onUploaded={(url)=>setUserPatch((p:any)=>({...p,coverImageUrl:url}))}/></div></div><input value={userPatch.websiteUrl||''} onChange={e=>setUserPatch((p:any)=>({...p,websiteUrl:e.target.value}))} placeholder="Website URL" className="border-2 border-black p-3 font-mono text-xs"/><input value={userPatch.location||''} onChange={e=>setUserPatch((p:any)=>({...p,location:e.target.value}))} placeholder="Location" className="border-2 border-black p-3 font-mono text-xs"/><input value={userPatch.socialX||''} onChange={e=>setUserPatch((p:any)=>({...p,socialX:e.target.value}))} placeholder="X URL" className="border-2 border-black p-3 font-mono text-xs"/><input value={userPatch.socialGithub||''} onChange={e=>setUserPatch((p:any)=>({...p,socialGithub:e.target.value}))} placeholder="GitHub URL" className="border-2 border-black p-3 font-mono text-xs"/><input value={userPatch.socialTelegram||''} onChange={e=>setUserPatch((p:any)=>({...p,socialTelegram:e.target.value}))} placeholder="Telegram URL" className="border-2 border-black p-3 font-mono text-xs"/><input value={userPatch.socialInstagram||''} onChange={e=>setUserPatch((p:any)=>({...p,socialInstagram:e.target.value}))} placeholder="Instagram URL" className="border-2 border-black p-3 font-mono text-xs md:col-span-2"/><textarea value={userPatch.bio||''} onChange={e=>setUserPatch((p:any)=>({...p,bio:e.target.value}))} placeholder="Bio" className="md:col-span-2 border-2 border-black p-3 font-mono text-xs min-h-24"/></div><div className="grid md:grid-cols-2 gap-2">{(['isBlocked','isSuspended','restrictCommenting','restrictPosting','restrictCommunities','restrictReactions','restrictFollowing'] as const).map(k=><label key={k} className="border-2 border-black p-3 font-mono text-[10px] font-black"><input type="checkbox" checked={!!userPatch[k]} onChange={e=>setUserPatch((p:any)=>({...p,[k]:e.target.checked}))}/> {k.replace(/[A-Z]/g,m=>` ${m}`).toUpperCase()}</label>)}</div><input value={userPatch.suspensionUntil||''} onChange={e=>setUserPatch((p:any)=>({...p,suspensionUntil:e.target.value||null}))} placeholder="Suspension expiry ISO string (optional)" className="w-full border-2 border-black p-3 font-mono text-xs"/><textarea value={userPatch.moderatorNote||''} onChange={e=>setUserPatch((p:any)=>({...p,moderatorNote:e.target.value}))} placeholder="Internal moderator note" className="w-full min-h-24 border-2 border-black p-3 font-mono text-xs"/><input type="number" min="0" max="999" value={userPatch.warningCount||0} onChange={e=>setUserPatch((p:any)=>({...p,warningCount:Number(e.target.value)}))} className="w-full border-2 border-black p-3 font-mono text-xs" placeholder="Warnings"/><div className="flex flex-wrap gap-2"><button onClick={()=>void saveUserControls()} className={pill(false)}><Save className="inline w-3 h-3 mr-1"/>SAVE CONTROLS</button><button onClick={async()=>{try{await forceProfileCleanup(editingUser.uid);setEditingUser(null);await loadCore();msg('Profile cleanup completed in Firestore.')}catch(e:any){msg(e?.message||'Profile cleanup failed.','error')}}} className={pill(false)}>CLEAN PROFILE</button><button onClick={async()=>{try{await resetUserPreferences(editingUser.uid);msg('User preferences reset in Firestore.')}catch(e:any){msg(e?.message||'Preference reset failed.','error')}}} className={pill(false)}>RESET PREFS</button></div></div></div>}

    {editingCommunity && <div className="fixed inset-0 z-[402] bg-black/70 p-4 grid place-items-center"><div className="bg-white border-4 border-black w-full max-w-3xl p-5 space-y-4 max-h-[90vh] overflow-y-auto"><div className="flex justify-between"><h3 className="font-display font-black uppercase">COMMUNITY CONTROL · c/{editingCommunity.slug}</h3><button onClick={()=>setEditingCommunity(null)}>✕</button></div><div className="grid md:grid-cols-2 gap-2"><input value={editingCommunity.name||''} onChange={e=>setEditingCommunity(c=>c?{...c,name:e.target.value}:c)} placeholder="Name" className="border-2 border-black p-3 font-mono text-xs"/><div className="border-2 border-black p-2 space-y-2"><div className="font-mono text-[9px] font-black uppercase">Community icon</div><input value={editingCommunity.iconUrl||''} onChange={e=>setEditingCommunity(c=>c?{...c,iconUrl:e.target.value}:c)} placeholder="Icon URL" className="border-2 border-black p-3 font-mono text-xs"/><MediaUploadButton folder="profile" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" label="UPLOAD ICON" compact cropAspect="1:1" cropShape="rect" outputWidth={1000} outputHeight={1000} onUploaded={(url)=>setEditingCommunity(c=>c?{...c,iconUrl:url}:c)}/></div><div className="border-2 border-black p-2 space-y-2"><div className="font-mono text-[9px] font-black uppercase">Community banner</div><input value={editingCommunity.bannerUrl||''} onChange={e=>setEditingCommunity(c=>c?{...c,bannerUrl:e.target.value}:c)} placeholder="Banner URL" className="border-2 border-black p-3 font-mono text-xs"/><MediaUploadButton folder="profile" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" label="UPLOAD BANNER" compact cropAspect="2:1" cropShape="rect" outputWidth={1600} outputHeight={800} onUploaded={(url)=>setEditingCommunity(c=>c?{...c,bannerUrl:url}:c)}/></div><select value={editingCommunity.defaultPostType||'discussion'} onChange={e=>setEditingCommunity(c=>c?{...c,defaultPostType:e.target.value as any}:c)} className="border-2 border-black p-3 font-mono text-xs"><option value="discussion">DISCUSSION</option><option value="blog">SCRPT</option><option value="question">QUESTION</option><option value="link">LINK</option><option value="poll">POLL</option></select></div><textarea value={editingCommunity.description||''} onChange={e=>setEditingCommunity(c=>c?{...c,description:e.target.value}:c)} placeholder="Description" className="w-full border-2 border-black p-3 font-mono text-xs min-h-24"/><textarea value={(editingCommunity.rules||[]).join('\n')} onChange={e=>setEditingCommunity(c=>c?{...c,rules:e.target.value.split('\n').filter(Boolean)}:c)} placeholder="Rules — one per line" className="w-full border-2 border-black p-3 font-mono text-xs min-h-24"/><div className="grid md:grid-cols-2 gap-2">{(['isPrivate','isLocked','isArchived','allowLinks','allowMedia'] as const).map(k=><label key={k} className="border-2 border-black p-3 font-mono text-[10px] font-black"><input type="checkbox" checked={!!(editingCommunity as any)[k]} onChange={e=>setEditingCommunity(c=>c?{...c,[k]:e.target.checked}:c)}/> {k.replace(/[A-Z]/g,m=>` ${m}`).toUpperCase()}</label>)}</div><button onClick={()=>void saveCommunity()} className={pill(false)}>SAVE COMMUNITY</button></div></div>}

    {editingMessage && <div className="fixed inset-0 z-[403] bg-black/70 p-4 grid place-items-center"><div className="bg-white border-4 border-black w-full max-w-2xl p-5 space-y-4"><div className="flex justify-between"><h3 className="font-display font-black uppercase">MESSAGE CONTROL</h3><button onClick={()=>setEditingMessage(null)}>✕</button></div><div className="font-mono text-[9px]">MESSAGE {editingMessage.id} · @{editingMessage.senderUsername} → {editingMessage.recipientId}</div><textarea value={messageDraft} onChange={e=>setMessageDraft(e.target.value)} className="w-full min-h-48 border-2 border-black p-3 font-mono text-xs"/><button onClick={async()=>{try{await adminUpdateMessage(editingMessage.id,messageDraft);setEditingMessage(null);await loadCore();msg('Message updated in Firestore.')}catch(e:any){msg(e?.message||'Message update failed.','error')}}} className={pill(false)}>SAVE MESSAGE</button></div></div>}

    {editingArticle && <div className="fixed inset-0 z-[405] bg-black/70 p-4 grid place-items-center"><div className="bg-white border-4 border-black w-full max-w-5xl p-5 space-y-4 max-h-[90vh] overflow-y-auto"><div className="flex justify-between"><h3 className="font-display font-black uppercase">MASTER ARTICLE EDITOR · JSON → FIRESTORE</h3><button onClick={()=>setEditingArticle(null)}>✕</button></div><p className="font-mono text-[9px]">This edits the complete stored article object. Category, topics, author metadata, cover, slug, content, publication flags and other fields can be changed here; Firestore rules still authorize the write.</p><textarea value={articleJson} onChange={e=>setArticleJson(e.target.value)} className="w-full min-h-[520px] border-2 border-black p-3 font-mono text-[10px]"/><div className="flex gap-2"><button onClick={()=>void saveEditedArticle()} className={pill(false)}>SAVE ARTICLE</button><button onClick={()=>setEditingArticle(null)} className={pill(false)}>CANCEL</button></div></div></div>}

    {revisionArticle && <div className="fixed inset-0 z-[406] bg-black/70 p-4 grid place-items-center"><div className="bg-white border-4 border-black w-full max-w-4xl p-5 space-y-4 max-h-[90vh] overflow-y-auto"><div className="flex justify-between"><h3 className="font-display font-black uppercase">REVISION HISTORY · {revisionArticle.slug}</h3><button onClick={()=>setRevisionArticle(null)}>✕</button></div>{revisions.map(r=><div key={r.id} className="border-2 border-black p-3 flex flex-wrap justify-between gap-3"><div><div className="font-display font-black">{r.title}</div><div className="font-mono text-[9px]">{r.action} · {r.createdAt?.toDate?.()?.toLocaleString?.()||'timestamp pending'} · {r.id}</div></div><div className="flex gap-2"><button onClick={()=>void duplicateRevision(r)} className={pill(false)}>DUPLICATE</button><button onClick={()=>void restoreRevision(r)} className={pill(false)}>RESTORE</button></div></div>)}{!revisions.length&&<div className="border-2 border-dashed border-black p-6 font-mono text-xs">No revisions returned.</div>}</div></div>}

    {commentTarget && <div className="fixed inset-0 z-[410] bg-black/70 p-4 grid place-items-center"><div className="bg-white border-4 border-black w-full max-w-lg p-5 space-y-4"><h3 className="font-display font-black uppercase">COMMENT MODERATION</h3><div className="font-mono text-[9px]">{commentTarget.path}</div><div className="font-mono text-xs">{commentTarget.content}</div><div className="flex gap-2"><button onClick={async()=>{try{if(commentTarget.sourceType==='article')await hideOrRestoreArticleComment(commentTarget.articleSlug!,commentTarget.id,!commentTarget.isHidden);else if(commentTarget.sourceType==='community_post')await hideOrRestoreCommunityPostComment(commentTarget.communityId!,commentTarget.postId!,commentTarget.id,!commentTarget.isHidden);else await hideOrRestorePostComment(commentTarget.postId!,commentTarget.id,!commentTarget.isHidden);setCommentTarget(null);await loadComments();msg('Comment moderation state written to Firestore.')}catch(e:any){msg(e?.message||'Comment moderation failed.','error')}}} className={pill(false)}>{commentTarget.isHidden?'RESTORE':'HIDE'}</button>{commentTarget.sourceType==='article'&&<button onClick={async()=>{try{const n=await removeArticleCommentReplies(commentTarget.articleSlug!,commentTarget.id);setCommentTarget(null);await loadComments();msg(`${n} replies marked deleted.`)}catch(e:any){msg(e?.message||'Reply removal failed.','error')}}} className={pill(false)}>REMOVE REPLIES</button>}<button onClick={()=>setCommentTarget(null)} className={pill(false)}>CLOSE</button></div></div></div>}

    {permissionTarget && <div className="fixed inset-0 z-[420] bg-black/70 p-4 grid place-items-center"><div className="bg-white border-4 border-black w-full max-w-2xl p-5 space-y-4"><div className="flex justify-between"><h3 className="font-display font-black uppercase">PERMISSIONS · @{permissionTarget.username||permissionTarget.displayName}</h3><button onClick={()=>setPermissionTarget(null)}>✕</button></div><div className="grid md:grid-cols-2 gap-2">{['manageReports','moderatePosts','moderateComments','manageUsers','editArticles','deleteArticles','viewAnalytics'].map(k=><label key={k} className="border-2 border-black p-3 font-mono text-[10px] font-black"><input type="checkbox" checked={!!moderatorPermissions[k]} onChange={e=>setModeratorPermissions(p=>({...p,[k]:e.target.checked}))}/> {k}</label>)}</div><button onClick={()=>void savePermissions()} className={pill(false)}>SAVE PERMISSIONS</button></div></div>}

    {section==='changelog' && master && <div className="space-y-5">
      <div className="border-2 border-black p-4 space-y-3">
        <h3 className="font-display font-black uppercase">CHANGELOG BUILDER {changelogDraft.id ? '· EDITING' : ''}</h3>
        <p className="font-mono text-[9px]">Published entries are stored in Firestore and appear on the public Changelog page in realtime. The built-in history remains a fallback only.</p>
        <div className="grid md:grid-cols-2 gap-2">
          <input value={changelogDraft.version} onChange={e=>setChangelogDraft(x=>({...x,version:e.target.value}))} placeholder="Version e.g. V75.4" className="border-2 border-black p-2 font-mono text-xs"/>
          <input value={changelogDraft.date} onChange={e=>setChangelogDraft(x=>({...x,date:e.target.value}))} placeholder="Date" className="border-2 border-black p-2 font-mono text-xs"/>
          <input value={changelogDraft.title} onChange={e=>setChangelogDraft(x=>({...x,title:e.target.value}))} placeholder="Release title" className="border-2 border-black p-2 font-mono text-xs"/>
          <select value={changelogDraft.kind} onChange={e=>setChangelogDraft(x=>({...x,kind:e.target.value}))} className="border-2 border-black p-2 font-mono text-xs"><option value="feature">FEATURE</option><option value="fix">FIX</option><option value="security">SECURITY</option><option value="maintenance">MAINTENANCE</option></select>
        </div>
        <textarea value={changelogDraft.changes} onChange={e=>setChangelogDraft(x=>({...x,changes:e.target.value}))} placeholder="One change per line" className="w-full min-h-32 border-2 border-black p-2 font-mono text-xs"/>
        <button onClick={()=>void saveNewChangelog()} className={pill(false)}>PUBLISH CHANGELOG ENTRY</button>
      </div>
      <div className="space-y-2">
        {changelogEntries.map(e=><div key={e.id} className="border-2 border-black p-3 bg-white"><div className="flex justify-between gap-3"><div><div className="font-mono text-[9px] font-black">{e.version} · {e.date}</div><div className="font-display font-black uppercase">{e.title}</div></div><div className="flex gap-2"><button onClick={()=>setChangelogDraft({id:e.id,version:e.version,date:e.date,title:e.title,changes:e.changes.join('\n'),kind:e.kind||'feature'})} className={pill(false)}>EDIT</button><button onClick={()=>void removeChangelog(e.id)} className={danger}>DELETE</button></div></div><ul className="mt-2 font-mono text-[10px]">{e.changes.map((c,i)=><li key={i}>→ {c}</li>)}</ul></div>)}
        {!changelogEntries.length && <div className="border-2 border-dashed border-black p-6 font-mono text-xs">NO CLOUD CHANGELOG ENTRIES.</div>}
      </div>
    </div>}

    <div className="flex justify-end"><button onClick={()=>void loadCore()} className={pill(false)} disabled={loading}><RefreshCw className="inline w-3 h-3 mr-1"/>REFRESH CLOUD STATE</button></div>
  </div>;
};
